function Enable-WebTls {
    try { [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12 } catch {}
    try { [Net.ServicePointManager]::ServerCertificateValidationCallback = { $true } } catch {}
}
function Save-WebFile {
    param([string[]]$Urls,[string]$OutFile)
    Enable-WebTls
    $last = $null
    foreach($url in $Urls){
        try {
            Invoke-WebRequest -Uri $url -OutFile $OutFile -UseBasicParsing -TimeoutSec 300 -ErrorAction Stop
            if((Test-Path -LiteralPath $OutFile) -and ((Get-Item -LiteralPath $OutFile).Length -gt 1000)){ return $true }
        } catch { $last = $_.Exception.Message }
    }
    throw ("Download failed: {0}" -f $last)
}
