function Get-FiveMOptimizeSelfPath {
    $p = $PSCommandPath; if(-not $p){ $p = $MyInvocation.MyCommand.Path }
    if(-not $p){ $p = Join-Path (Join-Path $env:LOCALAPPDATA "FiveMOptimize\Release") $Global:UpdateScriptName }
    return $p
}
function Get-FiveMOptimizeLocalHash {
    try {
        $self = Get-FiveMOptimizeSelfPath
        if($self -and (Test-Path -LiteralPath $self)){ return (Get-FileHash -LiteralPath $self -Algorithm SHA256).Hash }
    } catch {}
    return $null
}
function Test-FiveMOptimizeUpdateAvailable {
    # Returns hashtable: Available, RemoteSha, LocalSha, Size, Message
    $result = @{ Available = $false; RemoteSha = $null; LocalSha = $null; Size = 0; Message = "" }
    try {
        $local = Get-FiveMOptimizeLocalHash
        $result.LocalSha = $local
        $headers = @{ "User-Agent" = "FiveM-Optimize-Updater"; "Accept" = "application/vnd.github.v3+json" }
        $meta = Invoke-RestMethod -Uri $Global:UpdateMetaUrl -Headers $headers -TimeoutSec 20 -ErrorAction Stop
        # GitHub contents API returns sha (git blob) - for file compare use download + hash, or use sha if stored
        $remoteDownloadUrl = [string]$meta.download_url
        if(-not $remoteDownloadUrl){ $remoteDownloadUrl = "$($Global:UpdateCheckUrl)?t=$([DateTimeOffset]::UtcNow.ToUnixTimeSeconds())" }
        else { $remoteDownloadUrl = "$remoteDownloadUrl&t=$([DateTimeOffset]::UtcNow.ToUnixTimeSeconds())" }
        $tmp = Join-Path $env:TEMP ("fivem_opt_chk_" + [guid]::NewGuid().ToString("N") + ".bin")
        Invoke-WebRequest -Uri $remoteDownloadUrl -OutFile $tmp -UseBasicParsing -TimeoutSec 300 -ErrorAction Stop
        $remoteHash = (Get-FileHash -LiteralPath $tmp -Algorithm SHA256).Hash
        $result.RemoteSha = $remoteHash
        $result.Size = (Get-Item -LiteralPath $tmp).Length
        Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue
        if($local -and $remoteHash -and ($local -ne $remoteHash)){
            $result.Available = $true
            $result.Message = "Update available"
        } elseif(-not $local){
            $result.Available = $true
            $result.Message = "No local hash; treat as update"
        } else {
            $result.Message = "Up to date"
        }
    } catch {
        $result.Message = "Check failed: $($_.Exception.Message)"
    }
    return $result
}
function Get-FiveMOptimizeUpdateUrls {
    $t = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
    $urls = New-Object System.Collections.Generic.List[string]
    foreach($u in @($Global:UpdateMirrors)){
        if($u){ [void]$urls.Add(("{0}{1}t={2}" -f $u, $(if($u.Contains("?")){"&"}else{"?"}), $t)) }
    }
    return @($urls)
}
function Save-FiveMOptimizeRemoteStamp([string]$Value) {
    try {
        if(-not $Global:StateDir){ $Global:StateDir = Join-Path $env:LOCALAPPDATA "FiveMOptimize" }
        if(-not (Test-Path $Global:StateDir)){ New-Item $Global:StateDir -ItemType Directory -Force | Out-Null }
        Set-Content -Path (Join-Path $Global:StateDir "remote-blob.sha") -Value $Value -Encoding UTF8
    } catch {}
}
function Install-FiveMOptimizeUpdate {
    param([switch]$Silent)
    $self = Get-FiveMOptimizeSelfPath
    if(-not $self){ $self = Join-Path (Join-Path $env:LOCALAPPDATA "FiveMOptimize\Release") $Global:UpdateScriptName }
    $tmp = Join-Path $env:TEMP ("fivem_opt_upd_" + [guid]::NewGuid().ToString("N") + ".ps1")
    $ok = $false
    $last = $null
    Enable-WebTls
    foreach($url in (Get-FiveMOptimizeUpdateUrls)){
        try {
            if(Get-Command Add-Log -EA SilentlyContinue){ Add-Log ("Downloading update: {0}" -f $url) "#38BDF8" }
            Invoke-WebRequest -Uri $url -OutFile $tmp -UseBasicParsing -TimeoutSec 300 -ErrorAction Stop
            if((Test-Path -LiteralPath $tmp) -and ((Get-Item -LiteralPath $tmp).Length -gt 50000)){ $ok = $true; break }
        } catch { $last = $_.Exception.Message }
    }
    if(-not $ok){ throw ("Update download failed: {0}" -f $last) }
    $newHash = (Get-FileHash -LiteralPath $tmp -Algorithm SHA256).Hash
    $oldHash = $null
    if($self -and (Test-Path -LiteralPath $self)){ try { $oldHash = (Get-FileHash -LiteralPath $self -Algorithm SHA256).Hash } catch {} }
    if($oldHash -and $oldHash -eq $newHash){
        Save-FiveMOptimizeRemoteStamp $newHash
        if(Get-Command Add-Log -EA SilentlyContinue){ Add-Log "Already latest build." "#10B981" }
        try { Remove-Item $tmp -Force -EA SilentlyContinue } catch {}
        return $false
    }
    $destDir = Split-Path -Parent $self
    if(-not (Test-Path $destDir)){ New-Item $destDir -ItemType Directory -Force | Out-Null }
    $bak = "$self.bak"
    try { if(Test-Path -LiteralPath $self){ Copy-Item -LiteralPath $self -Destination $bak -Force } } catch {}
    Copy-Item -LiteralPath $tmp -Destination $self -Force
    try { Unblock-File -LiteralPath $self -EA SilentlyContinue } catch {}
    Save-FiveMOptimizeRemoteStamp $newHash
    if(Get-Command Add-Log -EA SilentlyContinue){ Add-Log ("Updated {0}" -f $self) "#10B981" }
    try { Remove-Item $tmp -Force -EA SilentlyContinue } catch {}
    $exe = "$env:WINDIR\System32\WindowsPowerShell\v1.0\powershell.exe"
    Start-Process -FilePath $exe -ArgumentList @("-NoLogo","-NoProfile","-STA","-ExecutionPolicy","Bypass","-File",('"{0}"' -f $self)) -WorkingDirectory $destDir -Verb RunAs | Out-Null
    try { $window.Close() } catch {}
    return $true
}
function Start-FiveMOptimizeUpdateCheck {
    param([switch]$AutoApply)
    try {
        $job = Start-Job -ScriptBlock {
            param($Urls,$MetaUrl)
            try { [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12 } catch {}
            try { [Net.ServicePointManager]::ServerCertificateValidationCallback = { $true } } catch {}
            $headers = @{ "User-Agent" = "FiveM-Optimize-Updater" }
            foreach($url in $Urls){
                try {
                    $tmp = Join-Path $env:TEMP ("fivem_opt_chk_" + [guid]::NewGuid().ToString("N") + ".bin")
                    Invoke-WebRequest -Uri $url -OutFile $tmp -UseBasicParsing -TimeoutSec 180 -Headers $headers -ErrorAction Stop
                    if((Test-Path $tmp) -and ((Get-Item $tmp).Length -gt 50000)){
                        $hash = (Get-FileHash -LiteralPath $tmp -Algorithm SHA256).Hash
                        $size = (Get-Item $tmp).Length
                        Remove-Item $tmp -Force -EA SilentlyContinue
                        return @{ Ok=$true; Hash=$hash; Size=$size; Url=$url }
                    }
                } catch {}
            }
            return @{ Ok=$false; Error="remote file not found on GitHub/jsDelivr" }
        } -ArgumentList @(,(Get-FiveMOptimizeUpdateUrls)), $Global:UpdateMetaUrl
        $timer = New-Object System.Windows.Threading.DispatcherTimer
        $timer.Interval = [TimeSpan]::FromMilliseconds(700)
        $timer.Tag = @{ Job=$job; AutoApply=[bool]$AutoApply; Started=[datetime]::UtcNow }
        $timer.Add_Tick({
            $state = $timer.Tag
            $j = $state.Job
            if(-not $j){ $timer.Stop(); return }
            if($j.State -eq 'Running'){
                if(((Get-Date).ToUniversalTime() - $state.Started).TotalSeconds -gt 50){
                    Stop-Job $j -EA SilentlyContinue; Remove-Job $j -Force -EA SilentlyContinue
                    $timer.Stop()
                    try { Add-Log "Update check timed out." "#F59E0B" } catch {}
                }
                return
            }
            $timer.Stop()
            try {
                $r = Receive-Job $j -ErrorAction SilentlyContinue
                Remove-Job $j -Force -EA SilentlyContinue
                if(-not $r -or -not $r.Ok){
                    try { Add-Log ("Update check: {0}" -f $(if($r){$r.Error}else{"no remote build yet"})) "#F59E0B" } catch {}
                    try { Add-Log "Upload FiveM_Optimize.ps1 to GitHub folder FiveM_Optimize on branch main." "#F59E0B" } catch {}
                    return
                }
                $local = Get-FiveMOptimizeLocalHash
                if($local -and $r.Hash -and ($local -eq $r.Hash)){
                    Save-FiveMOptimizeRemoteStamp $r.Hash
                    try { Add-Log ("Realtime: up to date ({0})" -f $r.Hash.Substring(0,10)) "#10B981" } catch {}
                    try { [System.Windows.MessageBox]::Show("Already up to date.","FiveM Optimize") | Out-Null } catch {}
                    return
                }
                try { Add-Log ("Realtime update found (~{0:N1} MB)" -f ($r.Size/1MB)) "#38BDF8" } catch {}
                $do = $state.AutoApply
                if(-not $do){
                    $ans = [System.Windows.MessageBox]::Show("New FiveM Optimize version found.`nUpdate and restart now?","FiveM Optimize",[System.Windows.MessageBoxButton]::YesNo,[System.Windows.MessageBoxImage]::Question)
                    $do = ($ans -eq [System.Windows.MessageBoxResult]::Yes)
                }
                if($do){
                    try { [void](Install-FiveMOptimizeUpdate -Silent) } catch { Add-Log ("Update apply failed: {0}" -f $_.Exception.Message) "#EF4444" }
                }
            } catch {
                try { Add-Log ("Update check error: {0}" -f $_.Exception.Message) "#EF4444" } catch {}
            }
        }.GetNewClosure())
        $timer.Start()
    } catch {
        try { Add-Log "Could not start update check: $($_.Exception.Message)" "#6B7280" } catch {}
    }
}

function Save-TweakState {
    try {
        if(-not(Test-Path $Global:StateDir)){New-Item -Path $Global:StateDir -ItemType Directory -Force|Out-Null}
        $json = @{Orig=$Global:Orig;AppliedKeys=$Global:AppliedKeys;TweakToggles=$Global:TweakToggles;OrigServices=$Global:OrigServices;OrigMisc=$Global:OrigMisc;ActiveNetPreset=$Global:ActiveNetPreset;ActiveGpuPreset=$Global:ActiveGpuPreset;SelectAllActive=$Global:SelectAllActive}|ConvertTo-Json -Depth 10
        # Plain JSON (protection/obfuscation removed)
        $json | Set-Content -Path $Global:StateFile -Encoding UTF8 -EA Stop
    } catch {}
}
function ConvertTo-HashtableDeep($obj) { if($null -eq $obj){return $null}; if($obj -is [System.Collections.IDictionary]){$h=@{};foreach($k in $obj.Keys){$h[$k]=ConvertTo-HashtableDeep $obj[$k]};return $h}; if($obj -is [PSCustomObject]){$h=@{};foreach($p in $obj.PSObject.Properties){$h[$p.Name]=ConvertTo-HashtableDeep $p.Value};return $h}; if(($obj -is [System.Collections.IEnumerable]) -and ($obj -isnot [string])){return @($obj|ForEach-Object{ConvertTo-HashtableDeep $_})}; return $obj }
function Load-TweakState {
    try {
        if(Test-Path $Global:StateFile){
            $rawText = Get-Content -Path $Global:StateFile -Raw -EA Stop
            $json = $null
            # Prefer plain JSON; fall back to old Base64+XOR protected format for compatibility
            try {
                $json = $rawText | ConvertFrom-Json -EA Stop
            } catch {
                try {
                    $encoded = ""
                    foreach($char in $rawText.ToCharArray()){ $encoded += [char]([int]$char -bxor 0x13) }
                    $bytes = [System.Convert]::FromBase64String($encoded)
                    $jsonStr = [System.Text.Encoding]::UTF8.GetString($bytes)
                    $json = $jsonStr | ConvertFrom-Json -EA Stop
                } catch {}
            }
            if($json){
                $raw = $json
                if($raw.Orig){$Global:Orig=ConvertTo-HashtableDeep $raw.Orig}
                if($raw.AppliedKeys){$Global:AppliedKeys=ConvertTo-HashtableDeep $raw.AppliedKeys}
                if($raw.TweakToggles){$Global:SavedTweakToggles=ConvertTo-HashtableDeep $raw.TweakToggles}
                if($raw.OrigServices){$Global:OrigServices=ConvertTo-HashtableDeep $raw.OrigServices}
                if($raw.OrigMisc){$Global:OrigMisc=ConvertTo-HashtableDeep $raw.OrigMisc}
                if($raw.ActiveNetPreset){$Global:ActiveNetPreset=$raw.ActiveNetPreset}
                if($raw.ActiveGpuPreset){$Global:ActiveGpuPreset=$raw.ActiveGpuPreset}
                if($null -ne $raw.SelectAllActive){$Global:SelectAllActive=[bool]$raw.SelectAllActive}
            }
        }
    } catch {}
}
