$script:EmbeddedLessProjectPs1GzB64 = @'

'@
function Get-LessProjectLocalPath {
    $names = @("LessProject.ps1","lessproject.ps1")
    $roots = New-Object System.Collections.Generic.List[string]
    try { if($PSCommandPath){ [void]$roots.Add((Split-Path -Parent $PSCommandPath)) } } catch {}
    try { if($MyInvocation.MyCommand.Path){ [void]$roots.Add((Split-Path -Parent $MyInvocation.MyCommand.Path)) } } catch {}
    try { [void]$roots.Add([string]$PWD) } catch {}
    try { [void]$roots.Add((Join-Path $env:LOCALAPPDATA "FiveMOptimize\Release")) } catch {}
    try { [void]$roots.Add((Join-Path $env:LOCALAPPDATA "LessProject")) } catch {}
    try { [void]$roots.Add((Join-Path $env:ProgramData "FiveM_Optimize")) } catch {}
    foreach($root in $roots){
        if([string]::IsNullOrWhiteSpace($root)){ continue }
        foreach($n in $names){
            $p = Join-Path $root $n
            if(Test-Path -LiteralPath $p -PathType Leaf){ return $p }
        }
    }
    return $null
}
function Expand-EmbeddedLessProjectPs1 {
    $dir = Join-Path $env:LOCALAPPDATA "FiveMOptimize"
    if(-not (Test-Path $dir)){ New-Item -Path $dir -ItemType Directory -Force | Out-Null }
    $out = Join-Path $dir "LessProject.ps1"
    $bytes = [Convert]::FromBase64String($script:EmbeddedLessProjectPs1GzB64)
    $ms = New-Object System.IO.MemoryStream(,$bytes)
    $gz = New-Object System.IO.Compression.GzipStream($ms, [IO.Compression.CompressionMode]::Decompress)
    $outMs = New-Object System.IO.MemoryStream
    $gz.CopyTo($outMs)
    $gz.Dispose(); $ms.Dispose()
    [IO.File]::WriteAllBytes($out, $outMs.ToArray())
    $outMs.Dispose()
    try { Unblock-File -LiteralPath $out -ErrorAction SilentlyContinue } catch {}
    return $out
}
function Start-LessProjectFromFile {
    $ps1 = $null
    try { $ps1 = Expand-EmbeddedLessProjectPs1 } catch {
        $ps1 = Get-LessProjectLocalPath
    }
    if(-not $ps1 -or -not (Test-Path -LiteralPath $ps1)){
        throw "แตก LessProject จาก FiveM Optimize ไม่สำเร็จ"
    }
    $exe = (Get-Command powershell.exe -EA SilentlyContinue).Source
    if(-not $exe){ $exe = "$env:WINDIR\System32\WindowsPowerShell\v1.0\powershell.exe" }
    $argList = @("-NoLogo","-NoProfile","-STA","-ExecutionPolicy","Bypass","-File",('"{0}"' -f $ps1),"-SkipSplash")
    Start-Process -FilePath $exe -ArgumentList $argList -WorkingDirectory (Split-Path -Parent $ps1) -Verb RunAs -ErrorAction Stop | Out-Null
    Add-Log ("Less Project (File): extracted and launched {0}" -f $ps1) "#A78BFA"
    if($CurrentTask){ $CurrentTask.Text = "Starting Less Project from bundled file..." }
}
function Start-LessProjectFromLink {
    if($CurrentTask){ $CurrentTask.Text = "Starting Less Project from link..." }
    Add-Log "Less Project (Link): irm Install-LessProject.ps1 | iex" "#22D3EE"
    $lessCmd = 'Set-ExecutionPolicy Bypass -Scope Process -Force; irm "https://raw.githubusercontent.com/poomwyee-netizen/less-project-/e6730ba/LessProject_FiveM_Optimizer/Install-LessProject.ps1" | iex'
    $exe = (Get-Command powershell.exe -ErrorAction SilentlyContinue).Source
    if([string]::IsNullOrWhiteSpace($exe)){ $exe = "$env:WINDIR\System32\WindowsPowerShell\v1.0\powershell.exe" }
    Start-Process -FilePath $exe -ArgumentList @("-NoExit","-NoProfile","-ExecutionPolicy","Bypass","-Command",$lessCmd) -ErrorAction Stop | Out-Null
}
