function Run-NoNagle{
    param($ToggleKey)
    Set-CurrentTask "Nagle's Algorithm -> Disabled"
    try{
        Invoke-DedupedGlobalTweak "NET_NoNagle" $ToggleKey {
            $ifRoot="HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces"
            $ifaces=Get-ChildItem -Path $ifRoot -EA SilentlyContinue
            $count=0
            foreach($i in $ifaces){
                Save-Orig "NET_NoNagle_$($i.PSChildName)_Ack" $i.PSPath "TcpAckFrequency"
                Save-Orig "NET_NoNagle_$($i.PSChildName)_Delay" $i.PSPath "TCPNoDelay"
                Set-RegValue $i.PSPath "TcpAckFrequency" 1|Out-Null
                Set-RegValue $i.PSPath "TCPNoDelay" 1|Out-Null
                $count++
            }
            Add-Log "Nagle's algorithm disabled on $count adapter(s)" "#9B5DE5"
        }
    } catch { Add-Log "Nagle disable failed" "#EF4444" }
}

$Global:BoostFpsFlagFile = Join-Path $Global:StateDir "boost-fps.ok"
function Test-BoostFpsReady {
    try { return [bool](Test-Path -LiteralPath $Global:BoostFpsFlagFile) } catch { return $false }
}
function Set-BoostFpsReady {
    try {
        if(-not (Test-Path $Global:StateDir)){ New-Item -Path $Global:StateDir -ItemType Directory -Force | Out-Null }
        Set-Content -Path $Global:BoostFpsFlagFile -Value ((Get-Date).ToString("o")) -Encoding UTF8
        $Global:BoostFpsApplied = $true
    } catch {}
}
function Invoke-RegDword([string]$Key,[string]$Name,[int]$Value){
    try {
        if(-not (Test-Path $Key)){ New-Item -Path $Key -Force | Out-Null }
        Set-ItemProperty -Path $Key -Name $Name -Value $Value -Type DWord -Force -ErrorAction Stop
        return $true
    } catch { Add-Log ("Boost FPS skip {0}\{1}: {2}" -f $Key,$Name,$_.Exception.Message) "#F59E0B"; return $false }
}
function Invoke-RegSz([string]$Key,[string]$Name,[string]$Value){
    try {
        if(-not (Test-Path $Key)){ New-Item -Path $Key -Force | Out-Null }
        Set-ItemProperty -Path $Key -Name $Name -Value $Value -Type String -Force -ErrorAction Stop
        return $true
    } catch { return $false }
}
function Run-BoostFps {
    Set-CurrentTask "Boost FPS (Apply-AllTweaks)"
    try { [void](Set-FiveMLaunchShortcut) } catch {}
    Add-Log "--- BOOST FPS START ---" "#34D399"
    # 1 Stop sync
    Invoke-RegDword "HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\SettingSync" "SyncPolicy" 5 | Out-Null
    foreach($g in @("Personalization","BrowserSettings","Credentials","Accessibility","Windows")){
        Invoke-RegDword "HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\SettingSync\Groups\$g" "Enabled" 0 | Out-Null
    }
    # 2 Telemetry
    Invoke-RegDword "HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Diagnostics\DiagTrack" "ShowedToastAtLevel" 1 | Out-Null
    Invoke-RegDword "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\DataCollection" "AllowTelemetry" 0 | Out-Null
    Invoke-RegDword "HKLM:\SOFTWARE\Policies\Microsoft\Windows\DataCollection" "AllowTelemetry" 0 | Out-Null
    Invoke-RegDword "HKLM:\SOFTWARE\Policies\Microsoft\Windows\DataCollection" "AllowDeviceNameInTelemetry" 0 | Out-Null
    Invoke-RegDword "HKLM:\SOFTWARE\Wow6432Node\Microsoft\Windows\CurrentVersion\Policies\DataCollection" "AllowTelemetry" 0 | Out-Null
    Invoke-RegDword "HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Privacy" "TailoredExperiencesWithDiagnosticDataEnabled" 0 | Out-Null
    Invoke-RegDword "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Diagnostics\DiagTrack\EventTranscriptKey" "EnableEventTranscript" 0 | Out-Null
    Invoke-RegDword "HKCU:\SOFTWARE\Microsoft\Siuf\Rules" "NumberOfSIUFInPeriod" 0 | Out-Null
    try { Remove-ItemProperty "HKCU:\SOFTWARE\Microsoft\Siuf\Rules" -Name PeriodInNanoSeconds -EA SilentlyContinue } catch {}
    Invoke-RegDword "HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\AdvertisingInfo" "Enabled" 0 | Out-Null
    Invoke-RegDword "HKCU:\Control Panel\International\User Profile" "HttpAcceptLanguageOptOut" 1 | Out-Null
    Invoke-RegDword "HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\Advanced" "Start_TrackProgs" 0 | Out-Null
    Invoke-RegDword "HKCU:\SOFTWARE\Microsoft\Speech_OneCore\Settings\OnlineSpeechPrivacy" "HasAccepted" 0 | Out-Null
    Invoke-RegDword "HKCU:\SOFTWARE\Microsoft\Personalization\Settings" "AcceptedPrivacyPolicy" 0 | Out-Null
    Invoke-RegDword "HKCU:\SOFTWARE\Microsoft\InputPersonalization" "RestrictImplicitInkCollection" 1 | Out-Null
    Invoke-RegDword "HKCU:\SOFTWARE\Microsoft\InputPersonalization" "RestrictImplicitTextCollection" 1 | Out-Null
    Invoke-RegDword "HKCU:\SOFTWARE\Microsoft\InputPersonalization\TrainedDataStore" "HarvestContacts" 0 | Out-Null
    Invoke-RegDword "HKLM:\SOFTWARE\Policies\Microsoft\Windows\System" "PublishUserActivities" 0 | Out-Null
    Invoke-RegDword "HKLM:\SOFTWARE\Policies\Microsoft\Windows\System" "UploadUserActivities" 0 | Out-Null
    Invoke-RegSz "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\CapabilityAccessManager\ConsentStore\userNotificationListener" "Value" "Deny" | Out-Null
    Invoke-RegSz "HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\CapabilityAccessManager\ConsentStore\location" "Value" "Deny" | Out-Null
    Invoke-RegSz "HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\CapabilityAccessManager\ConsentStore\appDiagnostics" "Value" "Deny" | Out-Null
    Invoke-RegSz "HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\CapabilityAccessManager\ConsentStore\userAccountInformation" "Value" "Deny" | Out-Null
    $cc="HKCU:\SOFTWARE\Policies\Microsoft\Windows\CloudContent"
    Invoke-RegDword $cc "ConfigureWindowsSpotlight" 2 | Out-Null
    Invoke-RegDword $cc "IncludeEnterpriseSpotlight" 0 | Out-Null
    Invoke-RegDword $cc "DisableWindowsSpotlightFeatures" 1 | Out-Null
    Invoke-RegDword $cc "DisableWindowsSpotlightWindowsWelcomeExperience" 1 | Out-Null
    Invoke-RegDword $cc "DisableWindowsSpotlightOnActionCenter" 1 | Out-Null
    Invoke-RegDword $cc "DisableWindowsSpotlightOnSettings" 1 | Out-Null
    Invoke-RegDword $cc "DisableThirdPartySuggestions" 1 | Out-Null
    Invoke-RegDword $cc "DisableTailoredExperiencesWithDiagnosticData" 1 | Out-Null
    Invoke-RegDword "HKLM:\SOFTWARE\Policies\Microsoft\Windows\CloudContent" "DisableThirdPartySuggestions" 1 | Out-Null
    Invoke-RegDword "HKLM:\SOFTWARE\Policies\Microsoft\Windows\CloudContent" "DisableWindowsConsumerFeatures" 1 | Out-Null
    # 3 Kernel
    $k="HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\kernel"
    Invoke-RegDword $k "SeTokenSingletonAttributesConfig" 3 | Out-Null
    Invoke-RegDword $k "obcaseinsensitive" 1 | Out-Null
    Invoke-RegDword $k "KernelSEHOPEnabled" 0 | Out-Null
    Invoke-RegDword $k "DisableExceptionChainValidation" 1 | Out-Null
    Invoke-RegDword $k "DistributeTimers" 1 | Out-Null
    Invoke-RegDword $k "DisableTsx" 1 | Out-Null
    Invoke-RegDword $k "MinimumDpcRate" 0 | Out-Null
    Invoke-RegDword $k "DpcQueueDepth" 1 | Out-Null
    Invoke-RegDword $k "ThreadDpcEnable" 1 | Out-Null
    Invoke-RegDword $k "SplitLargeCaches" 0 | Out-Null
    Invoke-RegDword $k "DpcWatchdogProfileOffset" 0 | Out-Null
    Invoke-RegDword $k "DpcTimeout" 0 | Out-Null
    Invoke-RegDword $k "DpcWatchdogPeriod" 0 | Out-Null
    Invoke-RegDword $k "MaximumDpcQueueDepth" 0 | Out-Null
    Invoke-RegDword $k "AdjustDpcThreshold" 0 | Out-Null
    Invoke-RegDword $k "IdealDpcRate" 0 | Out-Null
    try { & reg.exe add "HKLM\SYSTEM\CurrentControlSet\Control\Session Manager\kernel" /v ObUnsecureGlobalNames /t REG_MULTI_SZ /d "netfxcustomperfcounters.1.0\0SharedPerfIPCBlock\0Cor_Private_IPCBlock\0Cor_Public_IPCBlock_" /f | Out-Null } catch {}
    try { & reg.exe add "HKLM\SYSTEM\CurrentControlSet\Control\Session Manager\kernel" /v MitigationAuditOptions /t REG_BINARY /d 222222222222222222222222222222222222222222222222 /f | Out-Null } catch {}
    try { & reg.exe add "HKLM\SYSTEM\CurrentControlSet\Control\Session Manager\kernel" /v MitigationOptions /t REG_BINARY /d 222222222222222222222222222222222222222222222222 /f | Out-Null } catch {}
    # 4 Games MMCSS
    $g="HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games"
    Invoke-RegDword $g "GPU Priority" 8 | Out-Null
    Invoke-RegDword $g "Priority" 6 | Out-Null
    Invoke-RegSz $g "Scheduling Category" "High" | Out-Null
    Invoke-RegSz $g "SFIO Priority" "High" | Out-Null
    # 5 driver search
    Invoke-RegDword "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\DriverSearching" "SearchOrderConfig" 0 | Out-Null
    # 6 suggested apps
    $cdm="HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\ContentDeliveryManager"
    foreach($n in @("ContentDeliveryAllowed","OemPreInstalledAppsEnabled","PreInstalledAppsEnabled","PreInstalledAppsEverEnabled","SilentInstalledAppsEnabled","SoftLandingEnabled","SubscribedContentEnabled","FeatureManagementEnabled","SystemPaneSuggestionsEnabled","RemediationRequired")){
        Invoke-RegDword $cdm $n 0 | Out-Null
    }
    # 7 background
    Invoke-RegDword "HKCU:\Software\Microsoft\Windows\CurrentVersion\BackgroundAccessApplications" "GlobalUserDisabled" 1 | Out-Null
    Invoke-RegDword "HKCU:\Software\Microsoft\Windows\CurrentVersion\Search" "BackgroundAppGlobalToggle" 0 | Out-Null
    # 8-11 game bar / dvr / transparency / coalescing
    Invoke-RegDword "HKLM:\SOFTWARE\Microsoft\PolicyManager\default\ApplicationManagement\AllowGameDVR" "value" 0 | Out-Null
    Invoke-RegDword "HKLM:\SOFTWARE\Policies\Microsoft\Windows\GameDVR" "AllowGameDVR" 0 | Out-Null
    Invoke-RegDword "HKCU:\Software\Microsoft\Windows\CurrentVersion\GameDVR" "AppCaptureEnabled" 0 | Out-Null
    Invoke-RegDword "HKCU:\System\GameConfigStore" "GameDVR_Enabled" 0 | Out-Null
    Invoke-RegDword "HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Themes\Personalize" "EnableTransparency" 0 | Out-Null
    Invoke-RegDword "HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Power" "CoalescingTimerinterval" 0 | Out-Null
    # 12-13 power registry only (no Windows power PLAN import)
    Invoke-RegDword "HKLM:\SYSTEM\CurrentControlSet\Control\Power\PowerSettings\54533251-82be-4824-96c1-47b60b740d00\943c8cb6-6f93-4227-ad87-e9a3feec08d1" "Attributes" 2 | Out-Null
    Invoke-RegDword "HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Power" "HiberbootEnabled" 0 | Out-Null
    Invoke-RegDword "HKLM:\SYSTEM\CurrentControlSet\Control\Power\PowerThrottling" "PowerThrottlingOff" 1 | Out-Null
    Invoke-RegDword "HKLM:\SYSTEM\CurrentControlSet\Control\Power" "HibernateEnabledDefault" 0 | Out-Null
    # 14-16 mmcss / lazy / responsiveness
    Invoke-RegDword "HKLM:\SYSTEM\CurrentControlSet\Services\MMCSS" "Start" 2 | Out-Null
    Invoke-RegDword "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile" "NoLazyMode" 0 | Out-Null
    Invoke-RegDword "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile" "LazyModeTimeout" 150000 | Out-Null
    Invoke-RegDword "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile" "SystemResponsiveness" 0 | Out-Null
    # Only allowed power plan
    try { if(Get-Command Run-ZephyshadePow -EA SilentlyContinue){ Run-ZephyshadePow } } catch { Add-Log "Dominusless import after Boost FPS: $_" "#F59E0B" }
    Set-BoostFpsReady
    Add-Log "--- BOOST FPS DONE --- APPLY FIVEM PROFILE is now unlocked." "#34D399"
    Set-CurrentTask "Boost FPS applied. You can now APPLY FIVEM PROFILE."
    try { [System.Windows.MessageBox]::Show("Boost FPS เสร็จแล้ว`n`nตอนนี้กด APPLY FIVEM PROFILE ได้","FiveM Optimize",[System.Windows.MessageBoxButton]::OK,[System.Windows.MessageBoxImage]::Information) | Out-Null } catch {}
}

function Run-UltimatePlan{
    # Other Windows power plans are not used. This toggle only applies Dominusless.pow.
    Set-CurrentTask "Power plan: Dominusless only"
