function Run-NoTelemetry{
    Set-CurrentTask "Telemetry Service -> Disabled"
    try{
        Save-OrigService "CLEAN_NoTelemetry" "DiagTrack"
        Stop-Service DiagTrack -Force -EA SilentlyContinue
        Set-Service DiagTrack -StartupType Disabled -EA SilentlyContinue
        Add-Log "Telemetry (DiagTrack) service disabled" "#9B5DE5"
        
        # Extra services from os-services-tweaks.ps1
        foreach($svcName in @("MapsBroker","dmwappushservice","RemoteRegistry","Fax","RetailDemo","WMPNetworkSvc","PhoneSvc","AJRouter","lfsvc","PimIndexMaintenanceSvc","diagnosticshub.standardcollector.service","SSDPSRV","upnphost","TrkWks","TabletInputService")){
            try{
                $svc = Get-Service -Name $svcName -EA SilentlyContinue
                if($svc){
                    Save-OrigService "CLEAN_NoTelemetry_$svcName" $svcName
                    Stop-Service $svcName -Force -EA SilentlyContinue
                    Set-Service $svcName -StartupType Disabled -EA SilentlyContinue
                }
            } catch {}
        }
        Add-Log "Additional background services disabled (os-services list)" "#9B5DE5"

        $Global:AppliedKeys["CLEAN_NoTelemetry"]=$true
    } catch { Add-Log "Telemetry disable skipped" "#F59E0B" }
}
