function Run-CitizenFXIni {
    Set-CurrentTask "CitizenFX.ini Auto-Write"
    # Integrated from ASPAS_All_Tweaks.ps1 - full performance profile + launch flags
    $ini = @'
[Game]
IVPath=E:\Setup [com]\7). Grand Theft Auto V

[Input]
UseRawInput=1
DisableMouseSmoothing=1
DisableControllerDeadzone=1
RawInputBufferSize=512
RawInputBufferFlush=1
EnableLowLatencyInput=1
DisableKeyboardDebounce=1

[Renderer]
DisableVSync=1
ForceRenderAheadLimit=0
SwapChainUseWaitableSwapChain=1
EnableFramePacing=0
EnableTripleBuffering=0
DisableLatencyLimiter=1
WaitForVBlank=0
ReduceInputLatency=1
ImmediatePresent=1
DisableOcclusionQueries=1

[Streaming]
MaxStreamingRequests=50
MaxStreamingMemory=2000

[Addon]
net_maxMtu 1200
vid_budgetScale 0
ui_maxQueriesPerMinute 15
disable_vsync 1
disable_fog 1
disable_ambient_occlusion 1

cl_forceStreamingLegacy=false
enable_cloth=1
disable_ambient_occlusion=0
disable_fog=0
NV_disableShaderDiskCache=false
UseHighPriorityThreads=1
UseAudioThread=1
ClearInvalidPoolCache=1
IgnoreDifferentVideoCard=1
DisableResourceTimeouts=1
'@
    $targets = @(
        "$env:LOCALAPPDATA\FiveM\FiveM.app\CitizenFX.ini",
        "$env:LOCALAPPDATA\FiveM\CitizenFX.ini"
    )
    $written = 0
    foreach($t in $targets){
        $dir = Split-Path $t -Parent
        if(Test-Path $dir){
            try {
                # Backup existing
                if(Test-Path $t){ Copy-Item $t "$t.bak_fivemopt" -Force -EA SilentlyContinue }
                Set-Content -Path $t -Value $ini -Encoding UTF8 -Force
                $written++
                Add-Log "Wrote CitizenFX.ini -> $t" "#9B5DE5"
            } catch { Add-Log "CitizenFX.ini write failed: $t : $_" "#F59E0B" }
        }
    }
    # Also set common launch args via registry if CitizenFX key exists
    $cfx = "HKCU:\Software\CitizenFX\FiveM"
    if(-not (Test-Path $cfx)){ New-Item $cfx -Force -EA SilentlyContinue | Out-Null }
    Set-RegValue $cfx "CEFHardwareAcceleration" 0 | Out-Null
    if($written -eq 0){
        # FiveM not installed yet - write to ProgramData for user to copy
        $fallback = "$env:ProgramData\FiveM_Optimize_CitizenFX.ini"
        Set-Content -Path $fallback -Value $ini -Encoding UTF8 -Force
        Add-Log "FiveM folder not found - saved template to $fallback" "#F59E0B"
    }
    try { [void](Set-FiveMLaunchShortcut) } catch { Add-Log ("CitizenFX shortcut: {0}" -f $_.Exception.Message) "#F59E0B" }
    $Global:AppliedKeys["CitizenFX_Ini"]=$true
}

function Run-ImportNip {
    Set-CurrentTask "Import NVIDIA Profile (.nip)"
    $scriptRoot = if($PSScriptRoot){ $PSScriptRoot } elseif($PSCommandPath){ Split-Path $PSCommandPath -Parent } else { $env:TEMP }
    $candidates = @(
        (Join-Path $scriptRoot "nvidiaProfileInspector.exe"),
        (Join-Path $scriptRoot "nvidiaProfileInspector\nvidiaProfileInspector.exe"),
        "$env:ProgramData\FiveM_Optimize\nvidiaProfileInspector.exe",
        "$env:LOCALAPPDATA\FiveM_Optimize\nvidiaProfileInspector.exe",
        ".\nvidiaProfileInspector.exe"
    )
    $nipCandidates = @(
        (Join-Path $scriptRoot "Wishsensei Performance v1.nip"),
        (Join-Path $scriptRoot "Wishsensei_Performance_v1.nip"),
        "$env:ProgramData\FiveM_Optimize\Wishsensei Performance v1.nip",
        ".\Wishsensei Performance v1.nip"
    )
    $npi = $candidates | Where-Object { Test-Path $_ } | Select-Object -First 1
    $nip = $nipCandidates | Where-Object { Test-Path $_ } | Select-Object -First 1
    if(-not $npi){
        Add-Log "nvidiaProfileInspector.exe not found next to script - place it beside FiveM_Optimize.ps1" "#F59E0B"
        $Global:AppliedKeys["GPU_ImportNip"]=$true
        return
    }
    if(-not $nip){
        Add-Log ".nip profile not found - place 'Wishsensei Performance v1.nip' beside the script" "#F59E0B"
        $Global:AppliedKeys["GPU_ImportNip"]=$true
        return
    }
    try {
        # nvidiaProfileInspector import: -import profile.nip  (silent variants vary by build)
        $p = Start-Process -FilePath $npi -ArgumentList @("-silent","-import","`"$nip`"") -Wait -PassThru -WindowStyle Hidden -EA SilentlyContinue
        if(-not $p -or $p.ExitCode -ne 0){
            # fallback without -silent
            Start-Process -FilePath $npi -ArgumentList @("-import","`"$nip`"") -Wait -WindowStyle Hidden -EA SilentlyContinue | Out-Null
        }
        Add-Log "NVIDIA profile imported: $nip" "#9B5DE5"
    } catch {
        Add-Log "NVIDIA profile import failed: $_" "#EF4444"
    }
    $Global:AppliedKeys["GPU_ImportNip"]=$true
}



# ========== KaiPrime V2 full overlay ==========
function Run-KaiPrimeQoS {
    Set-CurrentTask "KaiPrime QoS DSCP 46 (FiveM)"
    foreach ($pair in @(
        @("HKLM:\SOFTWARE\Policies\Microsoft\Windows\QoS\KaiPrime",  "FiveM.exe",            "10240"),
        @("HKLM:\SOFTWARE\Policies\Microsoft\Windows\QoS\KaiPrime1", "FiveM_GTAProcess.exe", "20480")
    )) {
        $key = $pair[0]; $app = $pair[1]; $rate = $pair[2]
        if (-not (Test-Path $key)) { New-Item -Path $key -Force | Out-Null }
        Set-ItemProperty -Path $key -Name "Version" -Value "1.0" -Type String -Force -EA SilentlyContinue
        Set-ItemProperty -Path $key -Name "Application Name" -Value $app -Type String -Force -EA SilentlyContinue
        foreach ($v in "Protocol","Local Port","Local IP","Local IP Prefix Length","Remote Port","Remote IP","Remote IP Prefix Length") {
            Set-ItemProperty -Path $key -Name $v -Value "*" -Type String -Force -EA SilentlyContinue
        }
        Set-ItemProperty -Path $key -Name "DSCP Value" -Value "46" -Type String -Force -EA SilentlyContinue
        Set-ItemProperty -Path $key -Name "Throttle Rate" -Value $rate -Type String -Force -EA SilentlyContinue
    }
    $qos = "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\QoS"
    if (-not (Test-Path $qos)) { New-Item -Path $qos -Force | Out-Null }
    Set-ItemProperty -Path $qos -Name "Do not use NLA" -Value "1" -Type String -Force -EA SilentlyContinue
    try { Start-Process gpupdate -ArgumentList "/force" -WindowStyle Hidden -Wait -EA SilentlyContinue } catch {}
    Add-Log "KaiPrime QoS DSCP 46 applied + gpupdate" "#9B5DE5"
    $Global:AppliedKeys["KaiPrime_QoS"]=$true
}

function Run-KaiPrimeNicTweaks {
    Set-CurrentTask "KaiPrime NIC + netsh Tweaks"
    $classKey = "HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e972-e325-11ce-bfc1-08002be10318}"
    $nicValues = [ordered]@{
        "*DeviceSleepOnDisconnect"="0"; "*EEE"="0"; "*FlowControl"="0"
        "*InterruptModeration"="0"; "*WakeOnMagicPacket"="0"; "*WakeOnPattern"="0"
        "AutoPowerSaveModeEnabled"="0"; "DMACoalescing"="0"; "EEELinkAdvertisement"="0"
        "EeePhyEnable"="0"; "ITR"="0"; "ReduceSpeedOnPowerDown"="0"; "PowerDownPll"="0"
        "AdvancedEEE"="0"; "EnableGreenEthernet"="0"; "GigaLite"="0"; "PowerSavingMode"="0"
        "S5WakeOnLan"="0"; "SavePowerNowEnabled"="0"; "ULPMode"="0"
        "*SelectiveSuspend"="0"; "EnablePME"="0"; "EnableModernStandby"="0"
        "*ModernStandbyWoLMagicPacket"="0"; "EnableLLI"="1"
        "*ReceiveBuffers"="32"; "*TransmitBuffers"="64"; "*RSS"="1"; "*NumRssQueues"="2"
    }
    $count = 0
    Get-ChildItem $classKey -EA SilentlyContinue | ForEach-Object {
        $p = $_.PSPath
        $props = Get-ItemProperty -Path $p -EA SilentlyContinue
        if ($null -eq $props) { return }
        if ($null -eq $props.PSObject.Properties["*SpeedDuplex"] -and $null -eq $props.DriverDesc) { return }
        foreach ($name in $nicValues.Keys) {
            if ($null -ne $props.PSObject.Properties[$name]) {
                Set-ItemProperty -Path $p -Name $name -Value $nicValues[$name] -Type String -Force -EA SilentlyContinue
                $count++
            }
        }
        if ($null -ne $props.PSObject.Properties["PnPCapabilities"]) {
            Set-ItemProperty -Path $p -Name "PnPCapabilities" -Value 24 -Type DWord -Force -EA SilentlyContinue
        }
    }
    Add-Log "KaiPrime NIC values updated: $count" "#9B5DE5"
    try {
        Disable-NetAdapterBinding -Name "*" -ComponentID ms_lldp,ms_lltdio,ms_rspndr -EA SilentlyContinue
    } catch {}
    $cmds = @(
        "int tcp set global dca=enabled",
        "int tcp set global netdma=enabled",
        "int tcp set global timestamps=disabled",
        "int tcp set global rss=enabled",
        "int tcp set global nonsackrttresiliency=disabled",
        "int tcp set global initialRto=2000",
        "int ip set global taskoffload=enabled"
    )
    foreach ($c in $cmds) {
        try { Start-Process netsh -ArgumentList $c -WindowStyle Hidden -Wait -EA SilentlyContinue } catch {}
    }
    Add-Log "KaiPrime netsh NIC stack applied" "#9B5DE5"
    $Global:AppliedKeys["KaiPrime_NicTweaks"]=$true
}

function Run-KaiPrimeInternetReg {
    Set-CurrentTask "KaiPrime Realtek Internet Values"
    $classKey = "HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e972-e325-11ce-bfc1-08002be10318}"
    $vals = [ordered]@{
        "*FlowControl"="0"; "*PriorityVLANTag"="1"; "*InterruptModeration"="0"
        "*ReceiveBuffers"="4096"; "*TransmitBuffers"="8"; "*JumboPacket"="1514"
        "*IPChecksumOffloadIPv4"="0"; "*TCPChecksumOffloadIPv4"="0"; "*UDPChecksumOffloadIPv4"="0"
        "*TCPChecksumOffloadIPv6"="0"; "*UDPChecksumOffloadIPv6"="0"
        "*RSS"="0"; "*NumRssQueues"="1"; "*LsoV2IPv4"="0"; "*LsoV2IPv6"="0"
        "*WakeOnPattern"="0"; "*WakeOnMagicPacket"="0"; "*ModernStandbyWoLMagicPacket"="0"
        "S5WakeOnLan"="0"; "PowerDownPll"="0"; "*EEE"="0"; "EnableGreenEthernet"="0"
        "AdvancedEEE"="0"; "GigaLite"="0"; "PowerSavingMode"="0"; "*SelectiveSuspend"="0"
        "*SSIdleTimeout"="0"; "DisablePBA"="1"; "EnableEDT"="1"
    }
    $applied = 0; $found = @()
    Get-ChildItem $classKey -EA SilentlyContinue | ForEach-Object {
        $p = $_.PSPath
        $props = Get-ItemProperty -Path $p -EA SilentlyContinue
        if ($null -eq $props) { return }
        $mdi = $props.MatchingDeviceId; $desc = $props.DriverDesc
        $isTarget = $false
        if ($mdi -and $mdi -match "VEN_10EC&DEV_(8125|8126|8127|8168|8169|8161|8136|8139|2600|3000)") { $isTarget = $true }
        elseif ($desc -and $desc -match "Realtek.*(PCIe|Family Controller|GbE|2\.5GbE|5GbE|10GbE|FE)") { $isTarget = $true }
        if (-not $isTarget) { return }
        $found += $desc
        foreach ($name in $vals.Keys) {
            Set-ItemProperty -Path $p -Name $name -Value $vals[$name] -Type String -Force -EA SilentlyContinue
            $applied++
        }
    }
    if ($applied -eq 0) { Add-Log "No Realtek adapter found - KaiPrime internet.reg skipped" "#6B7280" }
    else {
        foreach ($d in ($found | Select-Object -Unique)) { Add-Log "KaiPrime Realtek target: $d" "#9B5DE5" }
        Add-Log "KaiPrime internet values applied ($applied writes)" "#9B5DE5"
        Get-NetAdapter -EA SilentlyContinue | Where-Object { $_.InterfaceDescription -match "Realtek" } | Restart-NetAdapter -EA SilentlyContinue
    }
    $Global:AppliedKeys["KaiPrime_InternetReg"]=$true
}

function Run-KaiPrimeFiveMPriority {
    Set-CurrentTask "KaiPrime FiveM Permanent Priority (IFEO High)"
    foreach ($exe in @("FiveM.exe","FiveM_GTAProcess.exe","CitizenFX.exe")) {
        $p = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\$exe\PerfOptions"
        if (-not (Test-Path $p)) { New-Item -Path $p -Force | Out-Null }
        Save-Orig "KaiPrime_IFEO_$exe" $p "CpuPriorityClass"
        Set-RegValue $p "CpuPriorityClass" 3 | Out-Null  # High
        Add-Log "IFEO High: $exe" "#9B5DE5"
    }
    # live boost if running
    foreach ($n in @("FiveM","FiveM_GTAProcess","CitizenFX")) {
        Get-Process -Name $n -EA SilentlyContinue | ForEach-Object {
            try { $_.PriorityClass = "High"; Add-Log "Live HIGH: $($_.ProcessName)" "#9B5DE5" } catch {}
        }
    }
    $Global:AppliedKeys["KaiPrime_FiveMPriority"]=$true
}

function Run-KaiPrimeFull {
    Set-CurrentTask "KaiPrime Full Stack Overlay"
    # 1) Win32PrioritySeparation SKIPPED (user locked)
    Add-Log "KaiPrime: Win32PrioritySeparation skipped (locked)" "#F59E0B"
    # 2) QoS
    Run-KaiPrimeQoS
    # 3) Timer (existing STR service path)
    if (Get-Command Run-TimerRes -EA SilentlyContinue) { Run-TimerRes }
    # 4) Input queues 16
    Run-KbQueue16
    Run-MouseQueue16
    # 5) FiveM permanent priority
    Run-KaiPrimeFiveMPriority
    # 6) MMCSS
    if (Get-Command Run-MMCSSGamesProfile -EA SilentlyContinue) { Run-MMCSSGamesProfile }
    Add-Log "KaiPrime Full Stack Overlay complete" "#10B981"
    $Global:AppliedKeys["KaiPrime_Full"]=$true
}



function Run-DrewRayzx {
    Set-CurrentTask "Drew first, then Rayzx"

    # ============================================================
    # 1) DREW.BAT FIRST (must run before rayzx)
    #    secedit /configure /db %TEMP%\secedit.sdb /cfg %TEMP%\policy.cfg /overwrite
    #    reg import %TEMP%\machine.reg
    #    reg import %TEMP%\user.reg
    #    gpupdate /force
    # ============================================================
    $tmpdir  = $env:TEMP
    $cfg     = Join-Path $tmpdir "policy.cfg"
    $sdb     = Join-Path $tmpdir "secedit.sdb"
    $machine = Join-Path $tmpdir "machine.reg"
    $user    = Join-Path $tmpdir "user.reg"

    Add-Log "=== DREW (step 1/2) ===" "#9B5DE5"

    if (Test-Path $cfg) {
        try {
            Start-Process -FilePath "secedit.exe" -ArgumentList @("/configure","/db",$sdb,"/cfg",$cfg,"/overwrite") -Wait -WindowStyle Hidden -EA SilentlyContinue | Out-Null
            Add-Log "drew: secedit /configure OK" "#9B5DE5"
        } catch { Add-Log "drew: secedit error: $_" "#F59E0B" }
    } else {
        Add-Log "drew: %TEMP%\\policy.cfg missing - secedit skipped" "#6B7280"
    }

    if (Test-Path $machine) {
        Start-Process -FilePath "reg.exe" -ArgumentList @("import", "`"$machine`"") -Wait -WindowStyle Hidden -EA SilentlyContinue | Out-Null
        Add-Log "drew: imported machine.reg" "#9B5DE5"
    } else {
        Add-Log "drew: %TEMP%\\machine.reg missing - skipped" "#6B7280"
    }

    if (Test-Path $user) {
        Start-Process -FilePath "reg.exe" -ArgumentList @("import", "`"$user`"") -Wait -WindowStyle Hidden -EA SilentlyContinue | Out-Null
        Add-Log "drew: imported user.reg" "#9B5DE5"
    } else {
        Add-Log "drew: %TEMP%\\user.reg missing - skipped" "#6B7280"
    }

    try {
        Start-Process -FilePath "gpupdate.exe" -ArgumentList @("/force") -Wait -WindowStyle Hidden -EA SilentlyContinue | Out-Null
        Add-Log "drew: gpupdate /force done" "#9B5DE5"
    } catch { Add-Log "drew: gpupdate failed" "#F59E0B" }

    # ============================================================
    # 2) RAYZX.REG AFTER drew (values / policy key tree)
    # ============================================================
    Add-Log "=== RAYZX (step 2/2) ===" "#9B5DE5"

    $rayzx = @'
Windows Registry Editor Version 5.00

[HKEY_CURRENT_USER\SOFTWARE\Policies]

[HKEY_CURRENT_USER\SOFTWARE\Policies\Microsoft]

[HKEY_CURRENT_USER\SOFTWARE\Policies\Microsoft\SystemCertificates]

[HKEY_CURRENT_USER\SOFTWARE\Policies\Microsoft\SystemCertificates\CA]

[HKEY_CURRENT_USER\SOFTWARE\Policies\Microsoft\SystemCertificates\CA\Certificates]

[HKEY_CURRENT_USER\SOFTWARE\Policies\Microsoft\SystemCertificates\CA\CRLs]

[HKEY_CURRENT_USER\SOFTWARE\Policies\Microsoft\SystemCertificates\CA\CTLs]

[HKEY_CURRENT_USER\SOFTWARE\Policies\Microsoft\SystemCertificates\Disallowed]

[HKEY_CURRENT_USER\SOFTWARE\Policies\Microsoft\SystemCertificates\Disallowed\Certificates]

[HKEY_CURRENT_USER\SOFTWARE\Policies\Microsoft\SystemCertificates\Disallowed\CRLs]

[HKEY_CURRENT_USER\SOFTWARE\Policies\Microsoft\SystemCertificates\Disallowed\CTLs]

[HKEY_CURRENT_USER\SOFTWARE\Policies\Microsoft\SystemCertificates\trust]

[HKEY_CURRENT_USER\SOFTWARE\Policies\Microsoft\SystemCertificates\trust\Certificates]

[HKEY_CURRENT_USER\SOFTWARE\Policies\Microsoft\SystemCertificates\trust\CRLs]

[HKEY_CURRENT_USER\SOFTWARE\Policies\Microsoft\SystemCertificates\trust\CTLs]

[HKEY_CURRENT_USER\SOFTWARE\Policies\Microsoft\SystemCertificates\TrustedPeople]

[HKEY_CURRENT_USER\SOFTWARE\Policies\Microsoft\SystemCertificates\TrustedPeople\Certificates]

[HKEY_CURRENT_USER\SOFTWARE\Policies\Microsoft\SystemCertificates\TrustedPeople\CRLs]

[HKEY_CURRENT_USER\SOFTWARE\Policies\Microsoft\SystemCertificates\TrustedPeople\CTLs]

[HKEY_CURRENT_USER\SOFTWARE\Policies\Microsoft\SystemCertificates\TrustedPublisher]

[HKEY_CURRENT_USER\SOFTWARE\Policies\Microsoft\SystemCertificates\TrustedPublisher\Certificates]

[HKEY_CURRENT_USER\SOFTWARE\Policies\Microsoft\SystemCertificates\TrustedPublisher\CRLs]

[HKEY_CURRENT_USER\SOFTWARE\Policies\Microsoft\SystemCertificates\TrustedPublisher\CTLs]

[HKEY_CURRENT_USER\SOFTWARE\Policies\Microsoft\Windows]

[HKEY_CURRENT_USER\SOFTWARE\Policies\Microsoft\Windows\CloudContent]

[HKEY_CURRENT_USER\SOFTWARE\Policies\Microsoft\Windows\CurrentVersion]

[HKEY_CURRENT_USER\SOFTWARE\Policies\Microsoft\Windows\CurrentVersion\Internet Settings]

[HKEY_CURRENT_USER\SOFTWARE\Policies\Microsoft\Windows\CurrentVersion\Internet Settings\5.0]

[HKEY_CURRENT_USER\SOFTWARE\Policies\Microsoft\Windows\CurrentVersion\Internet Settings\5.0\Cache]

[HKEY_CURRENT_USER\SOFTWARE\Policies\Microsoft\Windows\CurrentVersion\Internet Settings\Cache]

[HKEY_CURRENT_USER\SOFTWARE\Policies\Microsoft\Windows\DataCollection]

[HKEY_CURRENT_USER\SOFTWARE\Policies\Power]

[HKEY_CURRENT_USER\SOFTWARE\Policies\Power\PowerSettings]
'@
    $rayzxPath = Join-Path $env:TEMP "FiveMOpt_rayzx.reg"
    try {
        Set-Content -Path $rayzxPath -Value $rayzx -Encoding ASCII -Force
        $p = Start-Process -FilePath "reg.exe" -ArgumentList @("import", "`"$rayzxPath`"") -Wait -PassThru -WindowStyle Hidden -EA SilentlyContinue
        if ($p -and $p.ExitCode -eq 0) { Add-Log "rayzx.reg imported OK (after drew)" "#9B5DE5" }
        else { Add-Log "rayzx.reg import exit=$($p.ExitCode) - ensuring keys" "#F59E0B" }
    } catch { Add-Log "rayzx.reg error: $_" "#EF4444" }

    $rayzxKeys = @(
        "HKCU:\SOFTWARE\Policies",
        "HKCU:\SOFTWARE\Policies\Microsoft",
        "HKCU:\SOFTWARE\Policies\Microsoft\SystemCertificates",
        "HKCU:\SOFTWARE\Policies\Microsoft\SystemCertificates\CA",
        "HKCU:\SOFTWARE\Policies\Microsoft\SystemCertificates\CA\Certificates",
        "HKCU:\SOFTWARE\Policies\Microsoft\SystemCertificates\CA\CRLs",
        "HKCU:\SOFTWARE\Policies\Microsoft\SystemCertificates\CA\CTLs",
        "HKCU:\SOFTWARE\Policies\Microsoft\SystemCertificates\Disallowed",
        "HKCU:\SOFTWARE\Policies\Microsoft\SystemCertificates\Disallowed\Certificates",
        "HKCU:\SOFTWARE\Policies\Microsoft\SystemCertificates\Disallowed\CRLs",
        "HKCU:\SOFTWARE\Policies\Microsoft\SystemCertificates\Disallowed\CTLs",
        "HKCU:\SOFTWARE\Policies\Microsoft\SystemCertificates\trust",
        "HKCU:\SOFTWARE\Policies\Microsoft\SystemCertificates\trust\Certificates",
        "HKCU:\SOFTWARE\Policies\Microsoft\SystemCertificates\trust\CRLs",
        "HKCU:\SOFTWARE\Policies\Microsoft\SystemCertificates\trust\CTLs",
        "HKCU:\SOFTWARE\Policies\Microsoft\SystemCertificates\TrustedPeople",
        "HKCU:\SOFTWARE\Policies\Microsoft\SystemCertificates\TrustedPeople\Certificates",
        "HKCU:\SOFTWARE\Policies\Microsoft\SystemCertificates\TrustedPeople\CRLs",
        "HKCU:\SOFTWARE\Policies\Microsoft\SystemCertificates\TrustedPeople\CTLs",
        "HKCU:\SOFTWARE\Policies\Microsoft\SystemCertificates\TrustedPublisher",
        "HKCU:\SOFTWARE\Policies\Microsoft\SystemCertificates\TrustedPublisher\Certificates",
        "HKCU:\SOFTWARE\Policies\Microsoft\SystemCertificates\TrustedPublisher\CRLs",
        "HKCU:\SOFTWARE\Policies\Microsoft\SystemCertificates\TrustedPublisher\CTLs",
        "HKCU:\SOFTWARE\Policies\Microsoft\Windows",
        "HKCU:\SOFTWARE\Policies\Microsoft\Windows\CloudContent",
        "HKCU:\SOFTWARE\Policies\Microsoft\Windows\CurrentVersion",
        "HKCU:\SOFTWARE\Policies\Microsoft\Windows\CurrentVersion\Internet Settings",
        "HKCU:\SOFTWARE\Policies\Microsoft\Windows\CurrentVersion\Internet Settings\5.0",
        "HKCU:\SOFTWARE\Policies\Microsoft\Windows\CurrentVersion\Internet Settings\5.0\Cache",
        "HKCU:\SOFTWARE\Policies\Microsoft\Windows\CurrentVersion\Internet Settings\Cache",
        "HKCU:\SOFTWARE\Policies\Microsoft\Windows\DataCollection",
        "HKCU:\SOFTWARE\Policies\Power",
        "HKCU:\SOFTWARE\Policies\Power\PowerSettings"
    )
    foreach ($k in $rayzxKeys) {
        if (-not (Test-Path $k)) { New-Item -Path $k -Force -EA SilentlyContinue | Out-Null }
    }
    Add-Log "rayzx: policy keys ensured (after drew)" "#9B5DE5"

    $Global:AppliedKeys["Drew_RayzxPolicy"]=$true
}





function Get-ScriptBuddyDir {
    $candidates = @()
    if ($PSScriptRoot) { $candidates += $PSScriptRoot }
    if ($PSCommandPath) { $candidates += (Split-Path $PSCommandPath -Parent) }
    if ($MyInvocation.MyCommand.Path) { $candidates += (Split-Path $MyInvocation.MyCommand.Path -Parent) }
    $candidates += (Join-Path $env:ProgramData "FiveM_Optimize")
    $candidates += (Get-Location).Path
    foreach ($d in $candidates) {
        if ($d -and (Test-Path $d)) { return $d }
    }
    return $env:TEMP
}

