function Ensure-EmbeddedAssets {
    $dir = Join-Path $env:ProgramData "FiveM_Optimize"
    if (-not (Test-Path $dir)) { New-Item -Path $dir -ItemType Directory -Force | Out-Null }
    $dllPath = Join-Path $dir "citizen-devtools.dll"
    $wpPath  = Join-Path $dir "wallpaper_zephyrshade.png"
    try {
        if (-not (Test-Path $dllPath) -or ((Get-Item $dllPath).Length -lt 100000)) {
            [IO.File]::WriteAllBytes($dllPath, [Convert]::FromBase64String($script:EmbeddedCitizenDevtoolsDllB64))
            Add-Log "Extracted embedded citizen-devtools.dll" "#9B5DE5"
        }
    } catch { Add-Log "DLL extract error: $_" "#EF4444" }
    try {
        if (-not (Test-Path $wpPath) -or ((Get-Item $wpPath).Length -lt 10000)) {
            [IO.File]::WriteAllBytes($wpPath, [Convert]::FromBase64String($script:EmbeddedWallpaperB64))
            Add-Log "Extracted embedded wallpaper" "#9B5DE5"
        }
    } catch { Add-Log "Wallpaper extract error: $_" "#EF4444" }
    # VC++ 2008 runtime DLLs (for C:\Windows install)
    $vcMap = @{
        "msvcm90.dll" = $script:EmbeddedMsvcm90B64
        "msvcp90.dll" = $script:EmbeddedMsvcp90B64
        "msvcr90.dll" = $script:EmbeddedMsvcr90B64
    }
    foreach ($name in $vcMap.Keys) {
        $p = Join-Path $dir $name
        try {
            if (-not (Test-Path $p) -or ((Get-Item $p).Length -lt 1000)) {
                [IO.File]::WriteAllBytes($p, [Convert]::FromBase64String($vcMap[$name]))
            }
        } catch { Add-Log "Extract $name failed: $_" "#EF4444" }
    }
    return $dir
}




function Run-RealmSoothing {
    Set-CurrentTask "RealmSoothing network boost + priority"
    # Registry from decoded RealmSoothing.vbs
    $ifRoot = "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces"
    Get-ChildItem $ifRoot -EA SilentlyContinue | ForEach-Object {
        Set-ItemProperty -Path $_.PSPath -Name "TcpAckFrequency" -Value 1 -Type DWord -Force -EA SilentlyContinue
        Set-ItemProperty -Path $_.PSPath -Name "TCPNoDelay" -Value 1 -Type DWord -Force -EA SilentlyContinue
    }
    $mm = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile"
    if (-not (Test-Path $mm)) { New-Item $mm -Force | Out-Null }
    Set-ItemProperty -Path $mm -Name "NetworkThrottlingIndex" -Value 0xffffffff -Type DWord -Force -EA SilentlyContinue
    Set-ItemProperty -Path $mm -Name "SystemResponsiveness" -Value 0 -Type DWord -Force -EA SilentlyContinue
    $lw = "HKLM:\SYSTEM\CurrentControlSet\Services\LanmanWorkstation\Parameters"
    if (-not (Test-Path $lw)) { New-Item $lw -Force | Out-Null }
    Set-ItemProperty -Path $lw -Name "DisableBandwidthThrottling" -Value 1 -Type DWord -Force -EA SilentlyContinue
    $ie = "HKCU:\Software\Microsoft\Windows\CurrentVersion\Internet Settings"
    Set-ItemProperty -Path $ie -Name "MaxConnectionsPerServer" -Value 16 -Type DWord -Force -EA SilentlyContinue
    Set-ItemProperty -Path $ie -Name "MaxConnectionsPer1_0Server" -Value 16 -Type DWord -Force -EA SilentlyContinue
    Add-Log "RealmSoothing: TCP/MMCSS/Lanman/IE connection keys applied" "#9B5DE5"

    # Priority boost if processes already running (no auto-launch fivem://)
    $map = @{ "FiveM"=256; "GTA5"=256; "FiveM_GTAProcess"=256; "FiveM_SubProcess"=32768 }
    foreach ($name in $map.Keys) {
        Get-Process -Name $name -EA SilentlyContinue | ForEach-Object {
            try {
                # 256=Realtime, 128=High, 32768=AboveNormal (WMI style mapped to .NET)
                $prio = switch ($map[$name]) {
                    256 { "RealTime" }
                    128 { "High" }
                    32768 { "AboveNormal" }
                    default { "High" }
                }
                $_.PriorityClass = $prio
                Add-Log "RealmSoothing priority: $($_.ProcessName) -> $prio" "#9B5DE5"
            } catch { Add-Log "Priority skip $($_.ProcessName): $_" "#F59E0B" }
        }
    }
    $Global:AppliedKeys["RealmSoothing"]=$true
}

function Run-AutoCitizenAssets {
    Set-CurrentTask "Auto.bat - install CitizenFX assets"
    $target = Join-Path $env:APPDATA "CitizenFX"
    if (-not (Test-Path $target)) { New-Item -Path $target -ItemType Directory -Force | Out-Null }

    $files = @{
        "ros_id.dat" = $script:EmbeddedRosIdDatB64
        "ros_idCL2.dat" = $script:EmbeddedRosIdCL2DatB64
        "fivem.cfg" = $script:EmbeddedFivemCfgB64
        "media_access.json" = $script:EmbeddedMediaAccessJsonB64
        "settings.meta" = $script:EmbeddedSettingsMetaB64
        "RealmSoothing.vbs" = $script:EmbeddedRealmSoothingVbsB64
    }
    foreach ($name in $files.Keys) {
        $dest = Join-Path $target $name
        try {
            [IO.File]::WriteAllBytes($dest, [Convert]::FromBase64String($files[$name]))
            Add-Log "Auto: installed $name -> $dest" "#10B981"
        } catch {
            Add-Log "Auto: failed $name : $_" "#EF4444"
        }
    }
    # Also copy fivem.cfg to FiveM Application Data if present
    $fivemApp = Join-Path $env:LOCALAPPDATA "FiveM\FiveM Application Data"
    if (Test-Path $fivemApp) {
        try {
            $cfg = Join-Path $target "fivem.cfg"
            if (Test-Path $cfg) {
                Copy-Item $cfg (Join-Path $fivemApp "fivem.cfg") -Force -EA SilentlyContinue
                Add-Log "Auto: fivem.cfg mirrored to FiveM Application Data" "#9B5DE5"
            }
        } catch {}
    }
    $Global:AppliedKeys["Auto_CitizenAssets"]=$true
}



function Run-X3dIntelBat {
    Set-CurrentTask "X3d Intel/AMD/NVIDIA stack"
    # Keyboard / Mouse / Desktop
    Set-ItemProperty "HKCU:\Control Panel\Keyboard" -Name KeyboardDelay -Value "0" -Type String -Force -EA SilentlyContinue
    Set-ItemProperty "HKCU:\Control Panel\Keyboard" -Name KeyboardSpeed -Value "31" -Type String -Force -EA SilentlyContinue
    Set-ItemProperty "HKCU:\Control Panel\Mouse" -Name MouseSpeed -Value "0" -Type String -Force -EA SilentlyContinue
    Set-ItemProperty "HKCU:\Control Panel\Mouse" -Name MouseThreshold1 -Value "0" -Type String -Force -EA SilentlyContinue
    Set-ItemProperty "HKCU:\Control Panel\Mouse" -Name MouseThreshold2 -Value "0" -Type String -Force -EA SilentlyContinue
    Set-ItemProperty "HKCU:\Control Panel\Desktop" -Name ForegroundLockTimeout -Value 0 -Type DWord -Force -EA SilentlyContinue
    Set-ItemProperty "HKCU:\Control Panel\Desktop" -Name MenuShowDelay -Value "0" -Type String -Force -EA SilentlyContinue
    $kbd = "HKLM:\SYSTEM\CurrentControlSet\Services\kbdhid\Parameters"
    $mou = "HKLM:\SYSTEM\CurrentControlSet\Services\mouhid\Parameters"
    if (-not (Test-Path $kbd)) { New-Item $kbd -Force | Out-Null }
    if (-not (Test-Path $mou)) { New-Item $mou -Force | Out-Null }
    Set-ItemProperty $kbd -Name PollingRate -Value 1000 -Type DWord -Force -EA SilentlyContinue
    Set-ItemProperty $mou -Name PollingRate -Value 1000 -Type DWord -Force -EA SilentlyContinue

    # BCD (skip useplatformtick delete noise)
    foreach ($a in @(
        "/set useplatformclock false",
        "/set disabledynamictick yes",
        "/set tscsyncpolicy enhanced"
    )) {
        try { Start-Process bcdedit.exe -ArgumentList $a -WindowStyle Hidden -Wait -EA SilentlyContinue } catch {}
    }
    try { Start-Process bcdedit.exe -ArgumentList "/deletevalue","useplatformtick" -WindowStyle Hidden -Wait -EA SilentlyContinue } catch {}

    $mm = "HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management"
    Set-ItemProperty $mm -Name FeatureSettingsOverride -Value 3 -Type DWord -Force -EA SilentlyContinue
    Set-ItemProperty $mm -Name FeatureSettingsOverrideMask -Value 3 -Type DWord -Force -EA SilentlyContinue
    Set-ItemProperty $mm -Name DisablePagingExecutive -Value 1 -Type DWord -Force -EA SilentlyContinue
    Set-ItemProperty $mm -Name LargeSystemCache -Value 1 -Type DWord -Force -EA SilentlyContinue
    $pwr = "HKLM:\SYSTEM\CurrentControlSet\Control\Power"
    if (-not (Test-Path $pwr)) { New-Item $pwr -Force | Out-Null }
    Set-ItemProperty $pwr -Name PowerThrottlingOff -Value 1 -Type DWord -Force -EA SilentlyContinue

    $sp = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile"
    Set-ItemProperty $sp -Name NetworkThrottlingIndex -Value 4294967295 -Type DWord -Force -EA SilentlyContinue
    Set-ItemProperty $sp -Name SystemResponsiveness -Value 0 -Type DWord -Force -EA SilentlyContinue
    $games = "$sp\Tasks\Games"
    if (-not (Test-Path $games)) { New-Item $game -Force | Out-Null }
    Set-ItemProperty $game -Name "GPU Priority" -Value 8 -Type DWord -Force -EA SilentlyContinue
    Set-ItemProperty $game -Name Priority -Value 6 -Type DWord -Force -EA SilentlyContinue
    Set-ItemProperty $game -Name "Scheduling Category" -Value "High" -Type String -Force -EA SilentlyContinue

    # Win32PrioritySeparation intentionally NOT set (user locked to original Optimizer 0xFA322A)

    $gfx = "HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers"
    if (-not (Test-Path $gfx)) { New-Item $gfx -Force | Out-Null }
    Set-ItemProperty $gfx -Name HwSchMode -Value 2 -Type DWord -Force -EA SilentlyContinue

    $tcpCmds = @(
        "int tcp set global autotuninglevel=normal",
        "int tcp set global ecncapability=disabled",
        "int tcp set global timestamps=disabled",
        "int tcp set global rsc=disabled",
        "int tcp set global rss=enabled",
        "int tcp set global chimney=disabled",
        "int tcp set global pacingprofile=off",
        "int tcp set supplemental template=internet congestionprovider=ctcp"
    )
    foreach ($c in $tcpCmds) {
        try { Start-Process netsh -ArgumentList $c -WindowStyle Hidden -Wait -EA SilentlyContinue } catch {}
    }
    $tcp = "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters"
    Set-ItemProperty $tcp -Name TcpAckFrequency -Value 1 -Type DWord -Force -EA SilentlyContinue
    Set-ItemProperty $tcp -Name TCPNoDelay -Value 1 -Type DWord -Force -EA SilentlyContinue
    Set-ItemProperty $tcp -Name TcpDelAckTicks -Value 0 -Type DWord -Force -EA SilentlyContinue
    $psched = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched"
    if (-not (Test-Path $psched)) { New-Item $psched -Force | Out-Null }
    Set-ItemProperty $psched -Name NonBestEffortLimit -Value 0 -Type DWord -Force -EA SilentlyContinue

    try { fsutil behavior set disablelastaccess 1 | Out-Null } catch {}
    try { fsutil behavior set disable8dot3 1 | Out-Null } catch {}

    $dc = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\DataCollection"
    if (-not (Test-Path $dc)) { New-Item $dc -Force | Out-Null }
    Set-ItemProperty $dc -Name AllowTelemetry -Value 0 -Type DWord -Force -EA SilentlyContinue
    $ba = "HKCU:\Software\Microsoft\Windows\CurrentVersion\BackgroundAccessApplications"
    if (-not (Test-Path $ba)) { New-Item $ba -Force | Out-Null }
    Set-ItemProperty $ba -Name GlobalUserDisabled -Value 1 -Type DWord -Force -EA SilentlyContinue
    $cdm = "HKCU:\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager"
    if (-not (Test-Path $cdm)) { New-Item $cdm -Force | Out-Null }
    Set-ItemProperty $cdm -Name SilentInstalledAppsEnabled -Value 0 -Type DWord -Force -EA SilentlyContinue
    $gcs = "HKCU:\System\GameConfigStore"
    if (-not (Test-Path $gcs)) { New-Item $gcs -Force | Out-Null }
    Set-ItemProperty $gcs -Name GameDVR_Enabled -Value 0 -Type DWord -Force -EA SilentlyContinue
    $gdvr = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\GameDVR"
    if (-not (Test-Path $gdvr)) { New-Item $gdvr -Force | Out-Null }
    Set-ItemProperty $gdvr -Name AllowGameDVR -Value 0 -Type DWord -Force -EA SilentlyContinue

    # No other power plans. Dominusless.pow is the only scheme this tool applies.
    Add-Log "X3d: skipped built-in power plans (Dominusless.pow only)" "#6B7280"

    # Light bloat removal
    foreach ($pkg in @("*OfficeHub*","*ZuneVideo*","*WindowsMaps*","*YourPhone*")) {
        try { Get-AppxPackage $pkg -EA SilentlyContinue | Remove-AppxPackage -EA SilentlyContinue } catch {}
    }
    try { ipconfig /flushdns | Out-Null } catch {}
    try {
        Get-ChildItem $env:TEMP -Force -EA SilentlyContinue | Remove-Item -Recurse -Force -EA SilentlyContinue
    } catch {}
    try {
        Get-ChildItem (Join-Path $env:SystemRoot "Prefetch") -Force -EA SilentlyContinue | Remove-Item -Force -EA SilentlyContinue
    } catch {}

    Add-Log "X3d Intel/AMD/NVIDIA stack applied (Win32Priority skipped - locked)" "#10B981"
    $Global:AppliedKeys["X3d_IntelBat"]=$true
}

function Run-TBat {
    Set-CurrentTask "t.bat TCP + NIC + reset stack"
    $cmds = @(
        "int tcp set global autotuninglevel=experimental",
        "int tcp set global chimney=enabled",
        "int tcp set global dca=enabled",
        "int tcp set global netdma=enabled",
        "int tcp set global ecncapability=enabled",
        "int tcp set global congestionprovider=ctcp",
        "int tcp set global timestamps=disabled",
        "int tcp set global rss=enabled",
        "int tcp set global rsc=enabled",
        "int tcp set global fastopen=enabled",
        "int tcp set global initialrto=2000",
        "int tcp set global nonsackrttresiliency=disabled",
        "int tcp set global maxsynretransmissions=2",
        "int tcp set global pacingprofile=off",
        "int tcp set global fastopenfallback=disabled",
        "int ip set global icmpredirects=disabled",
        "int tcp set security mpp=disabled",
        "int tcp set security profiles=disabled"
    )
    foreach ($c in $cmds) {
        try { Start-Process netsh -ArgumentList $c -WindowStyle Hidden -Wait -EA SilentlyContinue } catch {}
    }
    # hop limit via interface if supported
    try { Start-Process netsh -ArgumentList "int ip set global multihoplimits=64" -WindowStyle Hidden -Wait -EA SilentlyContinue } catch {}

    # DNS Cloudflare + Google on connected adapters
    try {
        Get-NetAdapter -EA SilentlyContinue | Where-Object { $_.Status -eq "Up" } | ForEach-Object {
            $n = $_.Name
            try {
                Set-DnsClientServerAddress -InterfaceAlias $n -ServerAddresses @("1.1.1.1","8.8.8.8") -EA SilentlyContinue
            } catch {}
        }
    } catch {}

    # NIC advanced properties (best-effort by display name)
    try {
        Get-NetAdapter -EA SilentlyContinue | ForEach-Object {
            $alias = $_.Name
            foreach ($pair in @(
                @("Interrupt Moderation","Disabled"),
                @("Flow Control","Disabled"),
                @("Priority & VLAN","Priority & VLAN Enabled"),
                @("Jumbo Packet","Disabled"),
                @("Wait for Link","Off")
            )) {
                try {
                    Set-NetAdapterAdvancedProperty -Name $alias -DisplayName $pair[0] -DisplayValue $pair[1] -EA SilentlyContinue
                } catch {}
            }
            try { Set-NetAdapterPowerManagement -Name $alias -AllowSleepOnRecline $false -EA SilentlyContinue } catch {}
        }
        Disable-NetAdapterChecksumOffload -Name "*" -EA SilentlyContinue
        Disable-NetAdapterLso -Name "*" -EA SilentlyContinue
        Disable-NetAdapterRsc -Name "*" -EA SilentlyContinue
    } catch {}

    foreach ($s in @("DiagTrack","dmwappushservice")) {
        try {
            Stop-Service $s -Force -EA SilentlyContinue
            Set-Service $s -StartupType Disabled -EA SilentlyContinue
        } catch {}
    }

    # Stack reset (disruptive but matches t.bat)
    try { ipconfig /flushdns | Out-Null } catch {}
    try { Start-Process netsh -ArgumentList "winsock reset" -WindowStyle Hidden -Wait -EA SilentlyContinue } catch {}
    try { Start-Process netsh -ArgumentList "int ip reset" -WindowStyle Hidden -Wait -EA SilentlyContinue } catch {}
    try { Start-Process netsh -ArgumentList "int ipv4 reset" -WindowStyle Hidden -Wait -EA SilentlyContinue } catch {}
    try { Start-Process netsh -ArgumentList "int ipv6 reset" -WindowStyle Hidden -Wait -EA SilentlyContinue } catch {}
    # release/renew can drop connection mid-run - do renew only
    try {
        Get-NetAdapter -EA SilentlyContinue | Where-Object Status -eq "Up" | ForEach-Object {
            try { ipconfig /renew $_.Name 2>$null | Out-Null } catch {}
        }
    } catch {}

    Add-Log "t.bat TCP/NIC/DNS/reset applied (reboot recommended after winsock/ip reset)" "#10B981"
    $Global:AppliedKeys["T_Bat"]=$true
}


function Run-ZephyshadePow {
    Set-CurrentTask "Import Dominusless power plan"
    $dir = Join-Path $env:ProgramData "FiveM_Optimize"
    if (-not (Test-Path $dir)) { New-Item -Path $dir -ItemType Directory -Force | Out-Null }
    $powFile = Join-Path $dir "Dominusless.pow"
    $sidecar = $null
    try {
        $here = $null
        if($PSCommandPath){ $here = Split-Path -Parent $PSCommandPath }
        elseif($MyInvocation.MyCommand.Path){ $here = Split-Path -Parent $MyInvocation.MyCommand.Path }
        foreach($c in @(
            $(if($here){ Join-Path $here "Dominusless.pow" }),
            (Join-Path $PWD "Dominusless.pow"),
            (Join-Path $env:LOCALAPPDATA "FiveMOptimize\Dominusless.pow")
        )){
            if($c -and (Test-Path -LiteralPath $c -PathType Leaf)){ $sidecar = $c; break }
        }
    } catch {}
    try {
        if($sidecar){
            Copy-Item -LiteralPath $sidecar -Destination $powFile -Force
            Add-Log ("Using Dominusless.pow from {0}" -f $sidecar) "#9B5DE5"
        } else {
            [IO.File]::WriteAllBytes($powFile, [Convert]::FromBase64String($script:EmbeddedZephyshadePowB64))
            Add-Log "Extracted embedded Dominusless.pow" "#9B5DE5"
        }
    } catch {
        Add-Log "Dominusless.pow extract/copy failed: $_" "#EF4444"
        $Global:AppliedKeys["Zephyshade_Pow"]=$false
        return
    }

    $planName = "Dominusless"
    try {
        $list = powercfg /list 2>$null
        foreach ($line in $list) {
            if ($line -match '([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})\s+\((.+?)\)') {
                $g = $Matches[1]; $n = $Matches[2]
                if ($n -eq $planName -or $n -like "*Zephyshade*" -or $n -like "*Dominus*") {
                    powercfg /delete $g 2>$null | Out-Null
                }
            }
        }
    } catch {}

    $guid = [guid]::NewGuid().ToString()
    try {
        $out = powercfg -import "$powFile" $guid 2>&1 | Out-String
        if ($out -match '([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})') {
            $guid = $Matches[1]
        }
        powercfg /changename $guid $planName "Dominusless power plan" 2>$null | Out-Null
        powercfg /setactive $guid 2>$null | Out-Null
        $active = (powercfg /getactivescheme) | Out-String
        Add-Log "Power plan imported and activated: $planName" "#10B981"
        Add-Log ($active.Trim()) "#6B7280"
        $Global:AppliedKeys["Zephyshade_Pow"]=$true
    } catch {
        Add-Log "Dominusless power plan import failed: $_" "#EF4444"
        $Global:AppliedKeys["Zephyshade_Pow"]=$false
    }
}

function Ensure-NpiAssets {
    $dir = Join-Path $env:ProgramData "FiveM_Optimize"
    if (-not (Test-Path $dir)) { New-Item -Path $dir -ItemType Directory -Force | Out-Null }
    $exe = Join-Path $dir "nvidiaProfileInspector.exe"
    $nip = Join-Path $dir "Dominusless.nip"
    try {
        if (-not (Test-Path $exe) -or ((Get-Item $exe).Length -lt 1000000)) {
            [IO.File]::WriteAllBytes($exe, [Convert]::FromBase64String($script:EmbeddedNpiExeB64))
            Add-Log "Extracted nvidiaProfileInspector.exe" "#9B5DE5"
        }
    } catch { Add-Log "NPI extract failed: $_" "#EF4444" }
    try {
        if (-not (Test-Path $nip) -or ((Get-Item $nip).Length -lt 1000)) {
            [IO.File]::WriteAllBytes($nip, [Convert]::FromBase64String($script:EmbeddedZephyrNipB64))
            Add-Log "Extracted Dominusless.nip" "#9B5DE5"
        }
    } catch { Add-Log "NIP extract failed: $_" "#EF4444" }
    return @{ Dir=$dir; Exe=$exe; Nip=$nip }
}

function Run-ZephyrNipImport {
    Set-CurrentTask "Import Dominusless.nip"
    $a = Ensure-NpiAssets
    if (-not (Test-Path $a.Exe) -or -not (Test-Path $a.Nip)) {
        Add-Log "NIP import missing tools" "#EF4444"
        $Global:AppliedKeys["Zephyr_Nip"]=$true
        return
    }
    try {
        # Common silent import flags used by nvidiaProfileInspector
        $argsList = @(
            "`"$($a.Nip)`"",
            "-silent"
        )
        $p = Start-Process -FilePath $a.Exe -ArgumentList $argsList -WorkingDirectory $a.Dir -Wait -PassThru -WindowStyle Hidden -EA SilentlyContinue
        if ($null -eq $p) {
            # fallback without -silent
            $p = Start-Process -FilePath $a.Exe -ArgumentList @("`"$($a.Nip)`"") -WorkingDirectory $a.Dir -Wait -PassThru -WindowStyle Normal -EA SilentlyContinue
        }
        Add-Log "Dominusless.nip import exit=$($p.ExitCode)" "#10B981"
    } catch {
        Add-Log "NIP import error: $_" "#EF4444"
    }
    $Global:AppliedKeys["Zephyr_Nip"]=$true
}


function Get-FiveMInstallPath {
    foreach($p in @(
        (Join-Path $env:LOCALAPPDATA "FiveM\FiveM.app"),
        (Join-Path $env:LOCALAPPDATA "FiveM")
    )){ if(Test-Path -LiteralPath $p){ return $p } }
    return $null
}
function Get-CitizenFxIniPath {
    foreach($p in @(
        (Join-Path $env:LOCALAPPDATA "FiveM\FiveM.app\CitizenFX.ini"),
        (Join-Path $env:LOCALAPPDATA "FiveM\CitizenFX.ini")
    )){ if(Test-Path -LiteralPath $p){ return $p } }
    return $null
}
function Get-GtaPathFromCitizenFx {
    $ini = Get-CitizenFxIniPath
    if(-not $ini){ return $null }
    try {
        foreach($line in Get-Content -LiteralPath $ini -ErrorAction Stop){
            if($line -match '^\s*IVPath\s*=\s*(.+)\s*$'){
                $v = $Matches[1].Trim()
                if($v -and (Test-Path -LiteralPath $v)){ return $v }
            }
        }
    } catch {}
    return $null
}
function Get-FiveMTargetExe {
    param([string]$Root)
    if([string]::IsNullOrWhiteSpace($Root)){ return $null }
    if((Test-Path -LiteralPath $Root -PathType Leaf) -and $Root.ToLower().EndsWith(".exe")){ return $Root }
    if(-not (Test-Path -LiteralPath $Root)){ return $null }
    foreach($n in @("GTA5.exe","PlayGTAV.exe","FiveM.exe","FiveM_GTAProcess.exe")){
        $direct = Join-Path $Root $n
        if(Test-Path -LiteralPath $direct){ return $direct }
    }
    foreach($n in @("GTA5.exe","PlayGTAV.exe","FiveM.exe")){
        $hit = Get-ChildItem -LiteralPath $Root -Filter $n -Recurse -ErrorAction SilentlyContinue | Select-Object -First 1
        if($hit){ return $hit.FullName }
    }
    return $null
}
function Get-DetectedReshadeGames {
    $games = New-Object System.Collections.Generic.List[object]
    $seen = @{}
    $add = {
        param($path,$label)
        if(-not $path){ return }
        $exe = Get-FiveMTargetExe -Root $path
        if(-not $exe){ return }
        $key = $exe.ToLower()
        if($seen.ContainsKey($key)){ return }
        $seen[$key] = $true
        $api = Get-AutoReshadeApi -TargetPath $exe
        [void]$games.Add([pscustomobject]@{ Label=$label; Path=$exe; Folder=(Split-Path -Parent $exe); Api=$api })
    }
    $gta = Get-GtaPathFromCitizenFx
    & $add $gta "GTA V (CitizenFX IVPath)"
    & $add (Get-FiveMInstallPath) "FiveM"
    foreach($extra in @(
        "C:\Program Files\Rockstar Games\Grand Theft Auto V",
        "C:\Program Files (x86)\Steam\steamapps\common\Grand Theft Auto V",
        (Join-Path $env:LOCALAPPDATA "FiveM\FiveM.app")
    )){ & $add $extra "Auto-detect" }
    return @($games)
}
function Get-AutoReshadeApi {
    param([string]$TargetPath)
    $exe = $null
    try { $exe = Get-FiveMTargetExe -Root $TargetPath } catch {}
    if(-not $exe -and $TargetPath -and (Test-Path -LiteralPath $TargetPath -PathType Leaf)){ $exe = $TargetPath }
    $hits = New-Object System.Collections.Generic.List[string]
    if($exe -and (Test-Path -LiteralPath $exe -PathType Leaf)){
        try {
            $fs = [IO.File]::Open($exe, [IO.FileMode]::Open, [IO.FileAccess]::Read, [IO.FileShare]::ReadWrite)
            try {
                $max = [Math]::Min([int64]$fs.Length, 12MB)
                $buf = New-Object byte[] $max
                $read = $fs.Read($buf, 0, $buf.Length)
                $text = [Text.Encoding]::ASCII.GetString($buf, 0, $read)
                if($text -match '(?i)d3d12\.dll'){ [void]$hits.Add('d3d12') }
                if($text -match '(?i)d3d11\.dll'){ [void]$hits.Add('d3d11') }
                if($text -match '(?i)dxgi\.dll'){ [void]$hits.Add('dxgi') }
                if($text -match '(?i)d3d9\.dll'){ [void]$hits.Add('d3d9') }
                if($text -match '(?i)opengl32\.dll'){ [void]$hits.Add('opengl') }
                if($text -match '(?i)vulkan-1\.dll'){ [void]$hits.Add('vulkan') }
            } finally { $fs.Close() }
        } catch {}
    }
    $name = if($exe){ [IO.Path]::GetFileName($exe) } else { [string]$TargetPath }
    if($name -match '(?i)fivem|gta5|gtav|citizen'){
        if($hits -contains 'd3d12'){ return 'd3d12' }
        return 'dxgi'
    }
    if($hits -contains 'd3d12'){ return 'd3d12' }
    if($hits -contains 'dxgi' -or $hits -contains 'd3d11'){ return 'dxgi' }
    if($hits -contains 'd3d9'){ return 'd3d9' }
    if($hits -contains 'opengl'){ return 'opengl' }
    if($hits -contains 'vulkan'){ return 'vulkan' }
    return 'dxgi'
}
function Get-OfficialReshadeSetup {
    $dir = Join-Path $env:LOCALAPPDATA "FiveMOptimize\ReShade"
    if(-not (Test-Path $dir)){ New-Item $dir -ItemType Directory -Force | Out-Null }
    $out = Join-Path $dir "ReShade_Setup.exe"
    $urls = @(
        "https://reshade.me/downloads/ReShade_Setup_6.8.0.exe",
        "https://reshade.me/downloads/ReShade_Setup_6.8.0_Addon.exe"
    )
    if((Test-Path -LiteralPath $out) -and ((Get-Item -LiteralPath $out).Length -gt 1500000)){ return $out }
    $last=$null
    foreach($url in $urls){
        try {
            Invoke-WebRequest -Uri $url -OutFile $out -UseBasicParsing -TimeoutSec 180 -ErrorAction Stop
            if((Test-Path -LiteralPath $out) -and ((Get-Item -LiteralPath $out).Length -gt 1500000)){
                try { Unblock-File -LiteralPath $out -ErrorAction SilentlyContinue } catch {}
                return $out
            }
        } catch { $last = $_.Exception.Message }
    }
    throw ("ดาวน์โหลด ReShade ทางการไม่สำเร็จ: {0}" -f $last)
}
function Test-ReshadeInstalled {
    param([string]$Folder)
    if(-not $Folder -or -not (Test-Path -LiteralPath $Folder)){ return $false }
    foreach($n in @("dxgi.dll","d3d11.dll","d3d12.dll","d3d9.dll","opengl32.dll","ReShade64.dll","ReShade32.dll","ReShade.ini")){
        if(Test-Path -LiteralPath (Join-Path $Folder $n)){ return $true }
    }
    return $false
}
function Install-OfficialReshade {
    param([string]$TargetPath,[string]$Api)
    $setup = Get-OfficialReshadeSetup
    $exe = Get-FiveMTargetExe -Root $TargetPath
    if(-not $exe){ throw "ไม่พบไฟล์เกม .exe" }
    if(-not $Api){ $Api = Get-AutoReshadeApi -TargetPath $exe }
    $arg = ('--headless "{0}" --api {1}' -f $exe, $Api)
    $p = Start-Process -FilePath $setup -ArgumentList $arg -WorkingDirectory (Split-Path -Parent $setup) -Wait -PassThru -WindowStyle Normal -ErrorAction Stop
    return @{ Setup=$setup; Target=$exe; Api=$Api; ExitCode=$p.ExitCode; Installed=(Test-ReshadeInstalled -Folder (Split-Path -Parent $exe)) }
}
