function Install-AppHubPackage {
    param($App,[scriptblock]$Log)
    if(-not $Log){ $Log = { param($m) } }
    & $Log ("Installing {0}..." -f $App.Name)
    if($App.Id -eq "ReShade" -or $App.Url -eq "reshade-internal"){
        $games = @(Get-DetectedReshadeGames)
        if($games.Count -eq 0){ throw "ไม่พบ FiveM / GTA V สำหรับติดตั้ง ReShade" }
        $g = $games[0]
        $api = Get-AutoReshadeApi -TargetPath $g.Path
        & $Log ("ReShade target: {0}" -f $g.Path)
        & $Log ("API auto-detect: {0}" -f $api)
        $result = Install-OfficialReshade -TargetPath $g.Path -Api $api
        & $Log ("ReShade setup exit {0}" -f $result.ExitCode)
        if($result.Installed){ & $Log "ReShade installed." } else { & $Log "ReShade setup ran. Start the game and press Home." }
        return $true
    }
    $winget = $null
    try { $winget = (Get-Command winget.exe -ErrorAction SilentlyContinue).Source } catch {}
    if($winget -and $App.Winget){
        try {
            $p = Start-Process -FilePath $winget -ArgumentList @("install","--id",$App.Winget,"-e","--accept-package-agreements","--accept-source-agreements") -Wait -PassThru -WindowStyle Normal
            if($p.ExitCode -eq 0 -or $p.ExitCode -eq -1978335189){ & $Log ("Installed {0}" -f $App.Name); return $true }
            & $Log ("{0}: winget exit {1}, trying download" -f $App.Name,$p.ExitCode)
        } catch { & $Log ("{0}: winget failed, trying download" -f $App.Name) }
    }
    $openOnly = ($App.Url -match 'hyperx.com/pages' -or $App.Url -match 'nvidia.com/Download' -or $App.Url -match 'rzr.to/')
    if($App.Url -match '^https://' -and -not $openOnly){
        $dir = Join-Path $env:LOCALAPPDATA "FiveMOptimize\AppHub"
        if(-not (Test-Path $dir)){ New-Item $dir -ItemType Directory -Force | Out-Null }
        $file = Join-Path $dir ($App.Id + "-setup.exe")
        Invoke-WebRequest -Uri $App.Url -OutFile $file -UseBasicParsing -TimeoutSec 240 -ErrorAction Stop
        if(-not (Test-Path $file) -or ((Get-Item $file).Length -lt 30000)){ throw "ดาวน์โหลดไม่ครบ" }
        try { Unblock-File -LiteralPath $file -ErrorAction SilentlyContinue } catch {}
        $silent = $null
        switch($App.Id){
            "Chrome" { $silent = "/silent /install" }
            "Brave" { $silent = "/silent /install" }
            "Steam" { $silent = "/S" }
            "SevenZip" { $silent = "/S" }
            "OBS" { $silent = "/S" }
            "DirectX" { $silent = "/Q" }
            "CPUZ" { $silent = "/SILENT" }
            "Discord" { $silent = "-s" }
            "DiscordCanary" { $silent = "-s" }
        }
        if($silent){
            Start-Process -FilePath $file -ArgumentList $silent -WorkingDirectory $dir -WindowStyle Normal | Out-Null
        } else {
            Start-Process -FilePath $file -WorkingDirectory $dir -WindowStyle Normal | Out-Null
        }
        & $Log ("Launched {0} installer" -f $App.Name)
        return $true
    }
    Start-Process $App.Url | Out-Null
    & $Log ("Opened {0} download page" -f $App.Name)
    return $true
}
function Show-AppHubWindow {
    $xaml = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="EXE SHOP" Width="1180" Height="820" WindowStartupLocation="CenterScreen"
        Background="Transparent" FontFamily="Segoe UI" WindowStyle="None" AllowsTransparency="True" ResizeMode="CanResize">
  <Border CornerRadius="20" Background="#0B0B0F" BorderBrush="#1A1A22" BorderThickness="1">
    <DockPanel Margin="28,22,20,18">
      <DockPanel DockPanel.Dock="Top" Margin="0,0,0,16">
        <Button x:Name="HubClose" DockPanel.Dock="Right" Content="✕" Width="34" Height="34" Background="#16161C" Foreground="#9CA3AF" BorderThickness="0" Cursor="Hand"/>
        <StackPanel>
          <TextBlock Text="EXE SHOP" Foreground="#F4F4F5" FontSize="22" FontWeight="Bold"/>
          <TextBlock Text="Install apps by category" Foreground="#6B7280" FontSize="12" Margin="0,2,0,0"/>
        </StackPanel>
      </DockPanel>
      <StackPanel x:Name="FilterRow" DockPanel.Dock="Top" Orientation="Horizontal" Margin="0,0,0,18"/>
      <TextBlock x:Name="HubStatus" DockPanel.Dock="Bottom" Text="" Foreground="#6B7280" FontSize="11" Margin="4,10,0,0"/>
      <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled" Padding="0,0,8,0">
        <UniformGrid x:Name="HubGrid" Columns="4"/>
      </ScrollViewer>
    </DockPanel>
  </Border>
</Window>
"@
    $win = [Windows.Markup.XamlReader]::Parse($xaml)
    $grid = $win.FindName("HubGrid")
    $status = $win.FindName("HubStatus")
    $filterRow = $win.FindName("FilterRow")
    $catalog = @(Get-AppHubCatalog)
    $filters = @(@{Tab="All"; Cat="All"}, @{Tab="Utilities"; Cat="Utility"}, @{Tab="Gaming"; Cat="Gaming"}, @{Tab="Diagnostics"; Cat="Diagnostics"})
    $activeCat = "All"
    $chips = @{}
    $styleChip = {
        param($tab)
        foreach($f in $filters){
            $b = $chips[$f.Tab]
            if($f.Tab -eq $tab){
                $b.Background = New-Object Windows.Media.SolidColorBrush ([Windows.Media.ColorConverter]::ConvertFromString("#1C1C24"))
                $b.Foreground = New-Object Windows.Media.SolidColorBrush ([Windows.Media.ColorConverter]::ConvertFromString("#F4F4F5"))
                $b.BorderBrush = New-Object Windows.Media.SolidColorBrush ([Windows.Media.ColorConverter]::ConvertFromString("#3F3F46"))
            } else {
                $b.Background = New-Object Windows.Media.SolidColorBrush ([Windows.Media.ColorConverter]::ConvertFromString("#121218"))
                $b.Foreground = New-Object Windows.Media.SolidColorBrush ([Windows.Media.ColorConverter]::ConvertFromString("#9CA3AF"))
                $b.BorderBrush = New-Object Windows.Media.SolidColorBrush ([Windows.Media.ColorConverter]::ConvertFromString("#22222A"))
            }
        }
    }
    $makeCard = {
        param($app)
        $card = New-Object Windows.Controls.Border
        $card.Margin = New-Object Windows.Thickness 0,0,14,14
        $card.Padding = New-Object Windows.Thickness 16,14,16,14
        $card.CornerRadius = New-Object Windows.CornerRadius 16
        $card.Background = New-Object Windows.Media.SolidColorBrush ([Windows.Media.ColorConverter]::ConvertFromString("#121217"))
        $card.BorderBrush = New-Object Windows.Media.SolidColorBrush ([Windows.Media.ColorConverter]::ConvertFromString("#22222C"))
        $card.BorderThickness = New-Object Windows.Thickness 1
        $card.MinHeight = 148
        $dock = New-Object Windows.Controls.DockPanel
        $install = New-Object Windows.Controls.Button
        $install.Content = "Install"
        $install.Height = 36
        $install.FontSize = 13
        $install.Cursor = [Windows.Input.Cursors]::Hand
        $install.Background = New-Object Windows.Media.SolidColorBrush ([Windows.Media.ColorConverter]::ConvertFromString("#18181F"))
        $install.Foreground = New-Object Windows.Media.SolidColorBrush ([Windows.Media.ColorConverter]::ConvertFromString("#E5E7EB"))
        $install.BorderBrush = New-Object Windows.Media.SolidColorBrush ([Windows.Media.ColorConverter]::ConvertFromString("#2A2A34"))
        $install.BorderThickness = New-Object Windows.Thickness 1
        $install.Margin = New-Object Windows.Thickness 0,16,0,0
        [Windows.Controls.DockPanel]::SetDock($install, [Windows.Controls.Dock]::Bottom)
        $install.Tag = $app
        $install.Add_Click({
            param($s,$e)
            $target = $s.Tag
            $s.IsEnabled = $false
            $old = [string]$s.Content
            $s.Content = "Installing..."
            $status.Text = ("Installing {0}..." -f $target.Name)
            try {
                [void](Install-AppHubPackage -App $target -Log { param($m) $status.Text = $m; try { Add-Log $m "#A78BFA" } catch {} })
                $s.Content = "Installed"
            } catch {
                $status.Text = ("{0} failed: {1}" -f $target.Name, $_.Exception.Message)
                $s.Content = "Retry"
                try { Add-Log $status.Text "#EF4444" } catch {}
            } finally { $s.IsEnabled = $true }
        }.GetNewClosure())
        $top = New-Object Windows.Controls.StackPanel
        $top.Orientation = [Windows.Controls.Orientation]::Horizontal
        $icon = New-Object Windows.Controls.Border
        $icon.Width=36; $icon.Height=36
        $icon.CornerRadius = New-Object Windows.CornerRadius 10
        $icon.Background = New-Object Windows.Media.SolidColorBrush ([Windows.Media.ColorConverter]::ConvertFromString($app.Color))
        $icon.Margin = New-Object Windows.Thickness 0,0,12,0
        $letter = New-Object Windows.Controls.TextBlock
        $letter.Text=[string]$app.Letter
        $letter.FontWeight=[Windows.FontWeights]::Bold
        $letter.FontSize=14
        $letter.Foreground = New-Object Windows.Media.SolidColorBrush ([Windows.Media.Color]::FromRgb(255,255,255))
        $letter.HorizontalAlignment="Center"; $letter.VerticalAlignment="Center"
        $icon.Child=$letter
        $meta = New-Object Windows.Controls.StackPanel
        $name = New-Object Windows.Controls.TextBlock
        $name.Text=$app.Name
        $name.FontSize=15
        $name.FontWeight=[Windows.FontWeights]::SemiBold
        $name.Foreground = New-Object Windows.Media.SolidColorBrush ([Windows.Media.ColorConverter]::ConvertFromString("#F4F4F5"))
        $chip = New-Object Windows.Controls.Border
        $chip.CornerRadius = New-Object Windows.CornerRadius 8
        $chip.Background = New-Object Windows.Media.SolidColorBrush ([Windows.Media.ColorConverter]::ConvertFromString("#1A1A22"))
        $chip.Padding = New-Object Windows.Thickness 8,2,8,2
        $chip.Margin = New-Object Windows.Thickness 0,6,0,0
        $chip.HorizontalAlignment="Left"
        $chipText = New-Object Windows.Controls.TextBlock
        $chipText.Text=$app.Cat
        $chipText.FontSize=11
        $chipText.Foreground = New-Object Windows.Media.SolidColorBrush ([Windows.Media.ColorConverter]::ConvertFromString("#A1A1AA"))
        $chip.Child=$chipText
        [void]$meta.Children.Add($name)
        [void]$meta.Children.Add($chip)
        [void]$top.Children.Add($icon)
        [void]$top.Children.Add($meta)
        [void]$dock.Children.Add($install)
        [void]$dock.Children.Add($top)
        $card.Child=$dock
        return $card
    }
    $render = {
        $grid.Children.Clear()
        $items = if($activeCat -eq "All"){ $catalog } else { @($catalog | Where-Object { $_.Cat -eq $activeCat }) }
        foreach($app in $items){ [void]$grid.Children.Add((& $makeCard $app)) }
        $status.Text = ("{0} apps  ·  {1}" -f @($items).Count, $activeCat)
    }
    foreach($f in $filters){
        $b = New-Object Windows.Controls.Button
        $b.Content=$f.Tab
        $b.Height=34
        $b.MinWidth=88
        $b.Margin=New-Object Windows.Thickness 0,0,8,0
        $b.Padding=New-Object Windows.Thickness 14,0,14,0
        $b.FontSize=13
        $b.Cursor=[Windows.Input.Cursors]::Hand
        $b.BorderThickness=New-Object Windows.Thickness 1
        $b.Tag=$f.Cat
        $b.Add_Click({
            param($s,$e)
            $script:activeCat = [string]$s.Tag
            $activeCat = [string]$s.Tag
            $tab = [string]$s.Content
            & $styleChip $tab
            & $render
        }.GetNewClosure())
        $chips[$f.Tab]=$b
        [void]$filterRow.Children.Add($b)
    }
    $win.FindName("HubClose").Add_Click({ $win.Close() })
    $win.Add_MouseLeftButtonDown({ try { $win.DragMove() } catch {} })
    & $styleChip "All"
    & $render
    [void]$win.ShowDialog()
}

