        $result = Install-OfficialReshade -TargetPath $game.Path -Api $api
        $status.Text = ("ReShade {0} | API {1} | exit {2}" -f $game.Label, $api, $result.ExitCode)
        if($result.Installed){ $status.Text = ($status.Text + " | files verified") }
    }
    $games = @(Get-DetectedReshadeGames)
    if($games.Count -eq 0){
        $status.Text = "No FiveM / GTA V detected. Official setup can still be opened."
    } else {
        $status.Text = ("Detected {0} game(s)" -f $games.Count)
    }
    foreach($g in $games){
        $copy = $g
        $action = { & $installGame $copy }.GetNewClosure()
        $tag = ("Gaming · {0}" -f $g.Api.ToUpper())
        & $addCard $g.Label $tag "#8B5CF6" "R" $action
    }
    & $addCard "Official Setup" "Utility" "#5B21B6" "S" ({
        $status.Text = "Opening official ReShade setup..."
        $setup = Get-OfficialReshadeSetup
        Start-Process -FilePath $setup -WindowStyle Normal
        $status.Text = "Official ReShade window opened."
    }.GetNewClosure())
    & $addCard "Scan Again" "Utility" "#3F3F46" "?" ({
        $win.Close()
        Show-ReshadeInstallerWindow
    }.GetNewClosure())
    $win.FindName("RsClose").Add_Click({ $win.Close() })
    $win.Add_MouseLeftButtonDown({ try { $win.DragMove() } catch {} })
    if($games.Count -eq 1){
        $status.Text = "One game detected. Installing ReShade..."
        try { & $installGame $games[0]; $status.Text = "ReShade installed. Start the game and press Home." } catch { $status.Text = $_.Exception.Message }
    }
    [void]$win.ShowDialog()
}

function Get-FiveMLaunchArguments {
    return "-high -useallavailablecores -noBrowser -noPause -force-d3d11 -noVSync -refresh 120"
}
function Set-FiveMLaunchShortcut {
    $argsWanted = Get-FiveMLaunchArguments
    $exeCandidates = @(
        (Join-Path $env:LOCALAPPDATA "FiveM\FiveM.exe"),
        (Join-Path $env:LOCALAPPDATA "FiveM\FiveM.app\FiveM.exe")
    )
    $exe = $exeCandidates | Where-Object { Test-Path -LiteralPath $_ } | Select-Object -First 1
    $searchRoots = @(
        [Environment]::GetFolderPath("Desktop"),
        [Environment]::GetFolderPath("CommonDesktopDirectory"),
        (Join-Path $env:APPDATA "Microsoft\Windows\Start Menu\Programs"),
        (Join-Path $env:ProgramData "Microsoft\Windows\Start Menu\Programs"),
        (Join-Path $env:LOCALAPPDATA "FiveM")
    ) | Where-Object { $_ -and (Test-Path $_) }
    $links = New-Object System.Collections.Generic.List[string]
    foreach($root in $searchRoots){
        try {
            Get-ChildItem -LiteralPath $root -Filter *.lnk -Recurse -ErrorAction SilentlyContinue | ForEach-Object { [void]$links.Add($_.FullName) }
        } catch {}
    }
    $updated = 0
    $shell = $null
    try { $shell = New-Object -ComObject WScript.Shell } catch { throw "สร้าง WScript.Shell ไม่ได้" }
    foreach($lnkPath in $links){
        try {
            $lnk = $shell.CreateShortcut($lnkPath)
            $target = [string]$lnk.TargetPath
            $name = [IO.Path]::GetFileNameWithoutExtension($lnkPath)
            $isFiveM = ($target -match '(?i)fivem\.exe') -or ($name -match '(?i)^(fivem|sm)$') -or ($lnk.Description -match '(?i)fivem')
            if(-not $isFiveM){ continue }
            if($exe){ $lnk.TargetPath = $exe }
            $lnk.Arguments = $argsWanted
            if($exe){ $lnk.WorkingDirectory = Split-Path -Parent $exe }
            $lnk.Save()
            $updated++
            Add-Log ("Shortcut updated: {0} -> {1}" -f $lnkPath, $argsWanted) "#A78BFA"
        } catch {
            Add-Log ("Shortcut skip: {0} : {1}" -f $lnkPath, $_.Exception.Message) "#6B7280"
        }
    }
    if($exe -and $updated -eq 0){
        $dest = Join-Path ([Environment]::GetFolderPath("Desktop")) "FiveM.lnk"
        $lnk = $shell.CreateShortcut($dest)
        $lnk.TargetPath = $exe
        $lnk.Arguments = $argsWanted
        $lnk.WorkingDirectory = Split-Path -Parent $exe
        $lnk.Description = "FiveM"
        $lnk.Save()
        $updated++
        Add-Log ("Created desktop shortcut: {0}" -f $dest) "#A78BFA"
    }
    return @{ Updated=$updated; Arguments=$argsWanted; Exe=$exe }
}
function Write-ShyboyPreset {
    param([string]$Folder)
    if(-not $Folder){ return }
    if(-not (Test-Path -LiteralPath $Folder)){ New-Item $Folder -ItemType Directory -Force | Out-Null }
    $text = $script:EmbeddedShyboyPreset
    if(-not $text){ return }
    $utf8 = New-Object System.Text.UTF8Encoding $false
    [IO.File]::WriteAllText((Join-Path $Folder "Shyboy_SS1.ini"), $text, $utf8)
    [IO.File]::WriteAllText((Join-Path $Folder "ReShadePreset.ini"), $text, $utf8)
    $iniPath = Join-Path $Folder "ReShade.ini"
    $ini = @"
[GENERAL]
EffectSearchPaths=.\reshade-shaders\Shaders\**
TextureSearchPaths=.\reshade-shaders\Textures\**
PreprocessorDefinitions=RESHADE_DEPTH_LINEARIZATION_FAR_PLANE=1000.0,RESHADE_DEPTH_INPUT_IS_UPSIDE_DOWN=0,RESHADE_DEPTH_INPUT_IS_REVERSED=1,RESHADE_DEPTH_INPUT_IS_LOGARITHMIC=0
CurrentPresetPath=.\Shyboy_SS1.ini
PresetFiles=.\Shyboy_SS1.ini

[INPUT]
GamepadNavigation=0
KeyOverlay=36,0,0,0
"@
    [IO.File]::WriteAllText($iniPath, $ini, $utf8)
}
function Get-ReshadeZipPath {
    $dir = Join-Path $env:LOCALAPPDATA "FiveMOptimize"
    if(-not (Test-Path $dir)){ New-Item $dir -ItemType Directory -Force | Out-Null }
    $out = Join-Path $dir "Reshade.zip"
    if($script:EmbeddedReshadeZipB64){
        Add-Log "Extracting embedded ReShade pack..." "#A78BFA"
        $bytes = [Convert]::FromBase64String($script:EmbeddedReshadeZipB64)
        [IO.File]::WriteAllBytes($out, $bytes)
        try { Unblock-File -LiteralPath $out -ErrorAction SilentlyContinue } catch {}
        if(Test-Path -LiteralPath $out){ return $out }
    }
    foreach($d in @($PSScriptRoot, (Get-Location).Path, $dir, $env:TEMP)){
        if(-not $d){ continue }
        $hit = Join-Path $d "Reshade.zip"
        if(Test-Path -LiteralPath $hit){ return $hit }
    }
    throw "Reshade pack missing inside FiveM Optimize"
}
function Get-ReshadeInstallFolders {
    $folders = New-Object System.Collections.Generic.List[string]
    $seen = @{}
    $add = {
        param($folder)
        if(-not $folder){ return }
        if(-not (Test-Path -LiteralPath $folder)){ return }
        $key = $folder.TrimEnd('\','/').ToLower()
        if($seen.ContainsKey($key)){ return }
        $seen[$key] = $true
        [void]$folders.Add($folder)
    }
    foreach($g in @(Get-DetectedReshadeGames)){ & $add $g.Folder }
    $fivem = Get-FiveMInstallPath
    if($fivem){
        if(Test-Path -LiteralPath (Join-Path $fivem "FiveM.exe") -or (Split-Path -Leaf $fivem) -eq "FiveM.app"){ & $add $fivem }
        else { & $add (Join-Path $fivem "FiveM.app") }
    }
    $gta = Get-GtaPathFromCitizenFx
    & $add $gta
    return @($folders)
}
function Install-ReshadeFromZip {
    param([string]$ZipPath,[string]$DestFolder)
    if(-not (Test-Path -LiteralPath $ZipPath)){ throw "ไม่พบ Reshade.zip" }
    if(-not (Test-Path -LiteralPath $DestFolder)){ New-Item $DestFolder -ItemType Directory -Force | Out-Null }
    Add-Type -AssemblyName System.IO.Compression.FileSystem -ErrorAction SilentlyContinue
    $zip = [IO.Compression.ZipFile]::OpenRead($ZipPath)
    try {
        $copied = 0
        foreach($entry in $zip.Entries){
            $name = [string]$entry.FullName
            if([string]::IsNullOrWhiteSpace($name)){ continue }
            $norm = $name.Replace('/','\')
            $parts = @($norm.Split('\') | Where-Object { $_ -ne "" })
            if($parts.Count -eq 0){ continue }
            if($parts[0] -match '(?i)^reshade$'){ $parts = $parts[1..($parts.Count-1)] }
            if($parts.Count -eq 0){ continue }
            $leaf = $parts[-1]
            if($leaf -match '(?i)^reshade\.log$'){ continue }
            $rel = [string]::Join('\', $parts)
            if($norm.EndsWith('\') -or $entry.Length -eq 0 -and $leaf -notmatch '\.'){
                $dir = Join-Path $DestFolder $rel
                if(-not (Test-Path -LiteralPath $dir)){ New-Item $dir -ItemType Directory -Force | Out-Null }
                continue
            }
            $out = Join-Path $DestFolder $rel
            $dir = Split-Path -Parent $out
            if(-not (Test-Path -LiteralPath $dir)){ New-Item $dir -ItemType Directory -Force | Out-Null }
            $destStream = [IO.File]::Create($out)
            try {
                $src = $entry.Open()
                try { $src.CopyTo($destStream) } finally { $src.Dispose() }
            } finally { $destStream.Dispose() }
            $copied++
        }
    } finally { $zip.Dispose() }
    return $copied
}
function Install-ReshadeLikeAspas {
    $zip = Get-ReshadeZipPath
    if(-not $zip){ throw "แตก Reshade จาก FiveM Optimize ไม่สำเร็จ" }
    $cache = Join-Path $env:LOCALAPPDATA "FiveMOptimize"
    if(-not (Test-Path $cache)){ New-Item $cache -ItemType Directory -Force | Out-Null }
    $cached = Join-Path $cache "Reshade.zip"
    if($zip -ne $cached){
        try { Copy-Item -LiteralPath $zip -Destination $cached -Force } catch {}
    }
    $folders = @(Get-ReshadeInstallFolders)
    if($folders.Count -eq 0){
        try { Add-Type -AssemblyName System.Windows.Forms -ErrorAction SilentlyContinue } catch {}
        $dlg = New-Object System.Windows.Forms.FolderBrowserDialog
        $dlg.Description = "Select FiveM.app or GTA V folder for ReShade"
        if($dlg.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK){
            $folders = @($dlg.SelectedPath)
        }
    }
    if($folders.Count -eq 0){ throw "FiveM / GTA V folder not found. Click ReShade and pick the game folder." }
    $results = @()
    foreach($folder in $folders){
        Add-Log ("Extract Reshade.zip -> {0}" -f $folder) "#A78BFA"
        $n = Install-ReshadeFromZip -ZipPath $zip -DestFolder $folder
        try { Write-ShyboyPreset -Folder $folder } catch { Add-Log ("Preset write: {0}" -f $_.Exception.Message) "#F59E0B" }
        $ok = Test-ReshadeInstalled -Folder $folder
        Add-Log ("Copied {0} files. Verified={1}" -f $n, $ok) "#10B981"
        $results += ,[pscustomobject]@{ Installed=$ok; Folder=$folder; Files=$n; ExitCode=0 }
    }
    return @{ Mode="zip"; Games=$folders.Count; Results=$results }
}
function Run-ReshadeInstaller {
    param([switch]$Quiet)
    Set-CurrentTask "ReShade"
    try {
        Add-Log "Installing ReShade automatically..." "#A78BFA"
        $r = Install-ReshadeLikeAspas
        $ok = @($r.Results | Where-Object { $_.Installed -or $_.ExitCode -eq 0 }).Count
        Add-Log ("ReShade auto-install done. Games={0} OK={1}. Press Home in-game." -f $r.Games, $ok) "#10B981"
        if(-not $Quiet){
            [System.Windows.MessageBox]::Show(("ลง ReShade อัตโนมัติแล้ว ({0} เกม)`nเข้าเกมแล้วกด Home" -f $r.Games),"ReShade",[System.Windows.MessageBoxButton]::OK,[System.Windows.MessageBoxImage]::Information) | Out-Null
        }
    } catch {
        Add-Log ("ReShade auto-install failed: {0}" -f $_.Exception.Message) "#EF4444"
        if(-not $Quiet){
            [System.Windows.MessageBox]::Show("$($_.Exception.Message)","ReShade",[System.Windows.MessageBoxButton]::OK,[System.Windows.MessageBoxImage]::Warning) | Out-Null
        }
    }
    $Global:AppliedKeys["Reshade_Installer"]=$true
    $Global:TweakToggles["Reshade_Installer"]=$true
}
