function Run-QueenOptimize {
    Set-CurrentTask "Queen All Optimize (post-stack)"
    # 1) Import combined reg
    $dir = Join-Path $env:ProgramData "FiveM_Optimize"
    if (-not (Test-Path $dir)) { New-Item $dir -ItemType Directory -Force | Out-Null }
    $regFile = Join-Path $dir "Queen_All_Optimize_Combined.reg"
    try {
        [IO.File]::WriteAllBytes($regFile, [Convert]::FromBase64String($script:EmbeddedQueenRegB64))
        $p = Start-Process reg.exe -ArgumentList @("import", "`"$regFile`"") -Wait -PassThru -WindowStyle Hidden -EA SilentlyContinue
        Add-Log "Queen reg import exit=$($p.ExitCode)" "#9B5DE5"
    } catch { Add-Log "Queen reg failed: $_" "#EF4444" }

    # 2) Commands from Queen_All_Optimize_Commands.bat (no reboot)
    try {
        $nvsmi = "C:\Program Files\NVIDIA Corporation\NVSMI\nvidia-smi.exe"
        if (Test-Path $nvsmi) {
            Start-Process $nvsmi -ArgumentList "-e","0" -Wait -WindowStyle Hidden -EA SilentlyContinue | Out-Null
            Start-Process $nvsmi -ArgumentList "-acp","0" -Wait -WindowStyle Hidden -EA SilentlyContinue | Out-Null
            Add-Log "Queen: nvidia-smi ECC off + unrestricted clock policy" "#9B5DE5"
        } else {
            Add-Log "Queen: nvidia-smi not found - skipped ECC/ACP" "#6B7280"
        }
    } catch {}

    # DisableDynamicPstate + RMHdcpKeyglobZero on GPU class keys
    try {
        $classRoot = "HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e968-e325-11ce-bfc1-08002be10318}"
        Get-ChildItem $classRoot -EA SilentlyContinue | ForEach-Object {
            $p = $_.PSPath
            Set-ItemProperty -Path $p -Name "DisableDynamicPstate" -Value 1 -Type DWord -Force -EA SilentlyContinue
            Set-ItemProperty -Path $p -Name "RMHdcpKeyglobZero" -Value 1 -Type DWord -Force -EA SilentlyContinue
        }
        Add-Log "Queen: DisableDynamicPstate + HDCP keys on GPU class" "#9B5DE5"
    } catch {}

    $nvClient = "HKLM:\SOFTWARE\NVIDIA Corporation\NvControlPanel2\Client"
    if (-not (Test-Path $nvClient)) { New-Item $nvClient -Force | Out-Null }
    Set-ItemProperty $nvClient -Name OptInOrOutPreference -Value 0 -Type DWord -Force -EA SilentlyContinue
    $nvStart = "HKLM:\SYSTEM\CurrentControlSet\Services\nvlddmkm\Global\Startup"
    if (-not (Test-Path $nvStart)) { New-Item $nvStart -Force | Out-Null }
    Set-ItemProperty $nvStart -Name SendTelemetryData -Value 0 -Type DWord -Force -EA SilentlyContinue
    Set-ItemProperty "HKLM:\SYSTEM\CurrentControlSet\Control" -Name SvcHostSplitThresholdInKB -Value 0xffffffff -Type DWord -Force -EA SilentlyContinue
    Add-Log "Queen: telemetry off + SvcHostSplitThreshold" "#9B5DE5"

    # 3) Force Zephyshade Dominus power plan ONLY (user requirement)
    try {
        $list = powercfg /list 2>$null
        $guid = $null
        foreach ($line in $list) {
            if ($line -match '([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}).*\((.*)\)') {
                if ($Matches[2] -match 'Zephyshade|Zephyrshade|Dominus') {
                    $guid = $Matches[1]
                    break
                }
            }
        }
        if ($guid) {
            powercfg /setactive $guid 2>$null | Out-Null
            Add-Log "Power plan forced active: Zephyshade Dominus ($guid)" "#10B981"
        } elseif (Get-Command Run-ZephyshadePow -EA SilentlyContinue) {
            Run-ZephyshadePow
            Add-Log "Re-imported Zephyshade Dominus power plan" "#10B981"
        } else {
            Add-Log "Zephyshade power plan not found - run Zephyshade_Pow toggle" "#F59E0B"
        }
    } catch { Add-Log "Power plan enforce failed: $_" "#F59E0B" }

    $Global:AppliedKeys["Queen_Optimize"]=$true
}


