function Run-VC90Dlls {
    Set-CurrentTask "Install msvcm90/msvcp90/msvcr90 into C:\\Windows"
    $assetDir = Ensure-EmbeddedAssets
    $targets = @(
        $env:WINDIR,
        (Join-Path $env:WINDIR "System32"),
        (Join-Path $env:WINDIR "SysWOW64")
    )
    $names = @("msvcm90.dll","msvcp90.dll","msvcr90.dll")
    $ok = 0
    foreach ($name in $names) {
        $src = Join-Path $assetDir $name
        if (-not (Test-Path $src)) {
            Add-Log "Missing extracted $name" "#EF4444"
            continue
        }
        foreach ($dir in $targets) {
            if (-not (Test-Path $dir)) { continue }
            $dest = Join-Path $dir $name
            try {
                if (Test-Path $dest) {
                    try { Copy-Item $dest "$dest.bak_fivemopt" -Force -EA SilentlyContinue } catch {}
                    try { Remove-Item $dest -Force -EA Stop } catch {
                        try { Rename-Item $dest ($name + ".old_" + (Get-Date -Format "yyyyMMddHHmmss")) -Force -EA Stop } catch {
                            Add-Log "Locked: $dest" "#F59E0B"
                            continue
                        }
                    }
                }
                Copy-Item $src $dest -Force -EA Stop
                Add-Log "Installed $name -> $dest" "#10B981"
                $ok++
            } catch {
                Add-Log "Install $name to $dir failed: $_" "#EF4444"
            }
        }
    }
    if ($ok -eq 0) { Add-Log "No VC90 DLL installed (permissions or lock)" "#F59E0B" }
    $Global:AppliedKeys["VC90_Dlls"]=$true
}

function Run-FivemLagQoS {
    Set-CurrentTask "FivemLag QoS (VBS then CMD)"
    # === Step 1: Fivemlag.vbs values FIRST ===
    Add-Log "=== Fivemlag.vbs (step 1/2) ===" "#9B5DE5"
    $regPath = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\QoS\FiveMLag"
    if (-not (Test-Path $regPath)) { New-Item -Path $regPath -Force | Out-Null }
    $vals = [ordered]@{
        "Version" = "1.0"
        "Application Name" = "FiveM_GTAProcess.exe"
        "Protocol" = "*"
        "Local Port" = "*"
        "Local IP" = "*"
        "Local IP Prefix Length" = "*"
        "Remote Port" = "*"
        "Remote IP" = "*"
        "Remote IP Prefix Length" = "*"
        "DSCP Value" = "46"
        "Throttle Rate" = "-1"
    }
    foreach ($k in $vals.Keys) {
        Set-ItemProperty -Path $regPath -Name $k -Value $vals[$k] -Type String -Force -EA SilentlyContinue
    }
    Add-Log "VBS: QoS FiveMLag written (DSCP 46, Throttle -1 / unlimited, FiveM_GTAProcess.exe) [ASPAS]" "#9B5DE5"

    # === Step 2: Fivemlag.cmd same policy reinforce + gpupdate ===
    Add-Log "=== Fivemlag.cmd (step 2/2) ===" "#9B5DE5"
    foreach ($k in $vals.Keys) {
        New-ItemProperty -Path $regPath -Name $k -PropertyType String -Value $vals[$k] -Force -EA SilentlyContinue | Out-Null
    }
    try {
        Start-Process gpupdate -ArgumentList "/force" -WindowStyle Hidden -Wait -EA SilentlyContinue
        Add-Log "CMD: gpupdate /force done" "#9B5DE5"
    } catch {}
    Add-Log "FivemLag QoS complete (VBS then CMD order)" "#10B981"
    $Global:AppliedKeys["FivemLag_QoS"]=$true
}

