        "XblAuthManager","XboxNetApiSvc","XblGameSave","GamingServices","GamingServicesNet",
        "Spooler","WerSvc","RemoteRegistry","wuauserv","BITS","DoSvc","FontCache","MapsBroker",
        "lfsvc","WpcMonSvc","LanmanServer","SessionEnv","TermService","UmRdpService","RemoteAccess",
        "TabletInputService","wisvc","WaaSMedicSvc","wercplsupport","PcaSvc"
        # NOTE: intentionally NOT disabling WlanSvc here - kills WiFi; original 1.bat had it
    )
    foreach ($s in $svcs) {
