            Set-Service -Name $s -StartupType Disabled -EA SilentlyContinue
        } catch {}
    }
    Add-Log "1.bat: services stopped/disabled" "#9B5DE5"

    # Registry from 1.bat
    $regs = @(
        @("HKLM:\SOFTWARE\Policies\Microsoft\Windows Defender","DisableAntiSpyware",1,"DWord"),
        @("HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management","LargeSystemCache",1,"DWord"),
        @("HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management\PrefetchParameters","EnablePrefetcher",0,"DWord"),
        @("HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management\PrefetchParameters","EnableSuperfetch",0,"DWord"),
        @("HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile","SystemResponsiveness",0,"DWord"),
        @("HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games","GPU Priority",8,"DWord"),
        @("HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games","Priority",6,"DWord"),
        @("HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games","Scheduling Category","High","String"),
        @("HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games","SFIO Priority","High","String"),
        @("HKCU:\Software\Microsoft\Windows\CurrentVersion\GameDVR","AppCaptureEnabled",0,"DWord"),
        @("HKCU:\Software\Microsoft\Windows\CurrentVersion\GameDVR","HistoricalCaptureEnabled",0,"DWord"),
        @("HKCU:\Software\Microsoft\Windows\CurrentVersion\GameDVR","AutoGameModeEnabled",0,"DWord"),
        @("HKLM:\SOFTWARE\Microsoft\PolicyManager\default\ApplicationManagement\AllowGameDVR","value",0,"DWord"),
        @("HKCU:\Control Panel\Desktop","MenuShowDelay","0","String"),
        @("HKCU:\Control Panel\Desktop","AutoEndTasks","1","String"),
        @("HKCU:\Control Panel\Desktop","HungAppTimeout","1000","String"),
        @("HKCU:\Control Panel\Desktop","WaitToKillAppTimeout","2000","String"),
        @("HKLM:\SYSTEM\CurrentControlSet\Control","WaitToKillServiceTimeout","2000","String")
    )
    foreach ($r in $regs) {
        $p,$n,$v,$t = $r
        try {
            if (-not (Test-Path $p)) { New-Item -Path $p -Force | Out-Null }
            if ($t -eq "DWord") { Set-ItemProperty -Path $p -Name $n -Value ([int]$v) -Type DWord -Force -EA SilentlyContinue }
            else { Set-ItemProperty -Path $p -Name $n -Value ([string]$v) -Type String -Force -EA SilentlyContinue }
        } catch {}
    }
    Add-Log "1.bat: registry applied" "#9B5DE5"

    # bcdedit from 1.bat (no forced reboot here)
    $bcd = @(
        "/set disabledynamictick yes",
        "/set useplatformclock no",
        "/set tscsyncpolicy Enhanced",
        "/set hypervisorlaunchtype off"
    )
    foreach ($a in $bcd) {
        try { Start-Process bcdedit.exe -ArgumentList $a -WindowStyle Hidden -Wait -EA SilentlyContinue } catch {}
    }
    Add-Log "1.bat: bcdedit flags set (reboot later to apply fully)" "#9B5DE5"

    # Lightweight cleanup (safe subset - no wiping whole Temp blindly mid-run)
    $cleanPaths = @(
        (Join-Path $env:LOCALAPPDATA "Microsoft\Windows\INetCache"),
        (Join-Path $env:LOCALAPPDATA "Microsoft\Windows\INetCookies"),
        (Join-Path $env:LOCALAPPDATA "Microsoft\Windows\WebCache"),
        (Join-Path $env:APPDATA "Discord\Cache"),
        (Join-Path $env:APPDATA "Discord\Code Cache")
    )
    foreach ($cp in $cleanPaths) {
        if (Test-Path $cp) {
            try { Get-ChildItem $cp -Recurse -Force -EA SilentlyContinue | Remove-Item -Recurse -Force -EA SilentlyContinue } catch {}
        }
    }
    Add-Log "1.bat: cache cleanup done (no auto-reboot - original bat had shutdown /r)" "#9B5DE5"
    $Global:AppliedKeys["Batch1_Tweaks"]=$true
}


function Run-CitizenDevtoolsDll {
    Set-CurrentTask "Replace citizen-devtools.dll (embedded)"
    $assetDir = Ensure-EmbeddedAssets
    $src = Join-Path $assetDir "citizen-devtools.dll"
    if (-not (Test-Path $src)) {
        Add-Log "Embedded DLL extract failed" "#EF4444"
        $Global:AppliedKeys["CitizenDevtoolsDll"]=$true
        return
    }
    $destDirs = @(
        (Join-Path $env:LOCALAPPDATA "FiveM\FiveM Application Data"),
        (Join-Path $env:LOCALAPPDATA "FiveM\FiveM.app"),
        (Join-Path $env:LOCALAPPDATA "FiveM")
    )
    $replaced = 0
    foreach ($dir in $destDirs) {
        if (-not (Test-Path $dir)) { continue }
        $dest = Join-Path $dir "citizen-devtools.dll"
        try {
            if (Test-Path $dest) {
                try {
                    Copy-Item $dest "$dest.bak_fivemopt" -Force -EA SilentlyContinue
                    Remove-Item $dest -Force -EA Stop
                } catch {
                    try {
                        Rename-Item $dest ("citizen-devtools.dll.old_" + (Get-Date -Format "yyyyMMddHHmmss")) -Force -EA Stop
                    } catch {
                        Add-Log "DLL locked in $dir - close FiveM first" "#EF4444"
                        continue
                    }
                }
            }
            Copy-Item -Path $src -Destination $dest -Force -EA Stop
            Add-Log "citizen-devtools.dll installed -> $dest" "#10B981"
            $replaced++
        } catch {
            Add-Log "DLL install failed: $_" "#EF4444"
        }
    }
    if ($replaced -eq 0) {
        Add-Log "FiveM folder not found or DLL locked - close FiveM and re-run" "#F59E0B"
    }
    $Global:AppliedKeys["CitizenDevtoolsDll"]=$true
}


function Run-SetWallpaper {
    Set-CurrentTask "Set ZEPHYRSHADE wallpaper (embedded)"
    $assetDir = Ensure-EmbeddedAssets
    $src = Join-Path $assetDir "wallpaper_zephyrshade.png"
    if (-not (Test-Path $src)) {
        Add-Log "Embedded wallpaper extract failed" "#EF4444"
        $Global:AppliedKeys["SetWallpaper"]=$true
        return
    }
    $destDir = Join-Path $env:APPDATA "FiveM_Optimize"
    if (-not (Test-Path $destDir)) { New-Item -Path $destDir -ItemType Directory -Force | Out-Null }
    $dest = Join-Path $destDir "wallpaper_zephyrshade.png"
    try {
        Copy-Item $src $dest -Force
        Set-ItemProperty -Path "HKCU:\Control Panel\Desktop" -Name WallpaperStyle -Value "10" -Force -EA SilentlyContinue
        Set-ItemProperty -Path "HKCU:\Control Panel\Desktop" -Name TileWallpaper -Value "0" -Force -EA SilentlyContinue
        Set-ItemProperty -Path "HKCU:\Control Panel\Desktop" -Name Wallpaper -Value $dest -Force -EA SilentlyContinue
        if (-not ("Win32Wallpaper" -as [type])) {
            Add-Type -TypeDefinition @"
using System;
using System.Runtime.InteropServices;
public class Win32Wallpaper {
  [DllImport("user32.dll", SetLastError=true, CharSet=CharSet.Unicode)]
  public static extern bool SystemParametersInfo(int uAction, int uParam, string lpvParam, int fuWinIni);
}
"@
        }
        [Win32Wallpaper]::SystemParametersInfo(20, 0, $dest, 3) | Out-Null
        Start-Process rundll32.exe -ArgumentList "user32.dll,UpdatePerUserSystemParameters","1","True" -WindowStyle Hidden -EA SilentlyContinue
        Add-Log "Wallpaper set automatically" "#10B981"
    } catch {
        Add-Log "Wallpaper failed: $_" "#EF4444"
    }
    $Global:AppliedKeys["SetWallpaper"]=$true
}

function Run-GTASettingsXml {
    Set-CurrentTask "GTA/FiveM Graphics settings.xml (ASPAS profile)"
    # Integrated from ASPAS_All_Tweaks.ps1 - aggressive low settings + dynamic GPU name
    $gpus = @(Get-CimInstance Win32_VideoController -ErrorAction SilentlyContinue)
    $filtered = $gpus | Where-Object { $_.Name -notmatch "Microsoft Basic|Virtual|Remote|Citrix|VMware" }
    $discrete = $filtered | Where-Object {
        ($_.Name -match "NVIDIA|GeForce|RTX|GTX|Quadro|Radeon RX|Radeon Pro|Radeon HD|Arc") -and
        ($_.Name -notmatch "AMD Radeon\(TM\) Graphics|Intel.*HD|Intel.*UHD|Intel.*Iris")
    }
    if ($discrete) {
        $gpu = ($discrete | Sort-Object -Property AdapterRAM -Descending | Select-Object -First 1).Name
    } elseif ($filtered) {
        $gpu = ($filtered | Sort-Object -Property AdapterRAM -Descending | Select-Object -First 1).Name
    } else {
        $gpu = "NVIDIA GeForce RTX 4060"
    }

    $xml = @"
<?xml version="1.0" encoding="UTF-8"?>

<Settings>
  <version value="27" />
  <configSource>SMC_AUTO</configSource>
  <graphics>
    <Tessellation value="0" />
    <LodScale value="0.000000" />
    <PedLodBias value="0.200000" />
    <VehicleLodBias value="0.000000" />
    <ShadowQuality value="0" />
    <ReflectionQuality value="0" />
    <ReflectionMSAA value="8" />
    <SSAO value="0" />
    <AnisotropicFiltering value="16" />
    <MSAA value="0" />
    <MSAAFragments value="0" />
    <MSAAQuality value="0" />
    <SamplingMode value="0" />
    <TextureQuality value="2" />
    <ParticleQuality value="0" />
    <WaterQuality value="0" />
    <GrassQuality value="0" />
    <ShaderQuality value="0" />
    <Shadow_SoftShadows value="1" />
    <UltraShadows_Enabled value="false" />
    <Shadow_ParticleShadows value="true" />
    <Shadow_Distance value="1.000000" />
    <Shadow_LongShadows value="false" />
    <Shadow_SplitZStart value="0.930000" />
    <Shadow_SplitZEnd value="0.890000" />
    <Shadow_aircraftExpWeight value="0.990000" />
    <Shadow_DisableScreenSizeCheck value="false" />
    <Reflection_MipBlur value="true" />
    <FXAA_Enabled value="false" />
    <TXAA_Enabled value="false" />
    <Lighting_FogVolumes value="true" />
    <Shader_SSA value="true" />
    <DX_Version value="2" />
    <CityDensity value="0.000000" />
    <PedVarietyMultiplier value="0.000000" />
    <VehicleVarietyMultiplier value="0.000000" />
    <MacadamEdit value="0" />
    <HalfResResolution value="0" />
    <StepItUp value="false" />
    <Tessellation_ti value="0" />
    <Tessellation_vl value="false" />
    <Tessellation_vh value="false" />
  </graphics>
  <system>
    <numBytesPerReplayBlock value="9000000" />
    <numReplayBlocks value="36" />
    <maxSizeOfUSC value="104857600" />
    <maxBlocksInReplay value="0" />
  </system>
  <audio>
    <Audio3d value="false" />
  </audio>
  <video>
    <AdapterIndex value="0" />
    <OutputIndex value="0" />
    <ScreenWidth value="1920" />
    <ScreenHeight value="1080" />
    <RefreshRate value="144" />
    <Windowed value="1" />
    <VSync value="0" />
    <Stereo value="0" />
    <Convergence value="0.100000" />
    <Separation value="0.000000" />
    <PauseOnFocusLoss value="1" />
    <AspectRatio value="0" />
  </video>
  <VideoCardDescription>$gpu</VideoCardDescription>
</Settings>
"@

    $targets = @(
        (Join-Path $env:APPDATA "CitizenFX\gta5_settings.xml"),
        (Join-Path $env:USERPROFILE "Documents\Rockstar Games\GTA V\settings.xml"),
        (Join-Path $env:USERPROFILE "OneDrive\Documents\Rockstar Games\GTA V\settings.xml"),
        (Join-Path $env:LOCALAPPDATA "FiveM\FiveM.app\settings.xml")
    )
    $written = 0
    foreach ($t in $targets) {
        $dir = Split-Path $t -Parent
        if (-not (Test-Path $dir)) {
            try { New-Item -Path $dir -ItemType Directory -Force -EA SilentlyContinue | Out-Null } catch { continue }
        }
        try {
            if (Test-Path $t) {
                Set-ItemProperty $t -Name IsReadOnly -Value $false -ErrorAction SilentlyContinue
                Copy-Item $t "$t.bak_fivemopt" -Force -EA SilentlyContinue
            }
            [System.IO.File]::WriteAllText($t, $xml, (New-Object System.Text.UTF8Encoding($false)))
            Add-Log "Wrote settings.xml (ASPAS) -> $t (GPU: $gpu)" "#9B5DE5"
            $written++
        } catch { Add-Log "settings.xml failed $t : $_" "#F59E0B" }
    }
    if ($written -eq 0) {
        $fb = Join-Path $env:ProgramData "FiveM_Optimize\settings.xml"
        New-Item -Path (Split-Path $fb) -ItemType Directory -Force -EA SilentlyContinue | Out-Null
        [System.IO.File]::WriteAllText($fb, $xml, (New-Object System.Text.UTF8Encoding($false)))
        Add-Log "No GTA folder found - template saved to $fb" "#F59E0B"
    }
    $Global:AppliedKeys["GTA_SettingsXml"]=$true
}


$BtnRun.Add_Click({
    if(-not (Test-BoostFpsReady)){
        Add-Log "APPLY blocked: press Boost FPS first." "#F59E0B"
        [System.Windows.MessageBox]::Show("ต้องกดปุ่ม Boost FPS ก่อน แล้วค่อยกด APPLY FIVEM PROFILE","FiveM Optimize",[System.Windows.MessageBoxButton]::OK,[System.Windows.MessageBoxImage]::Warning) | Out-Null
        return
    }
    try { [void](Set-FiveMLaunchShortcut) } catch {}
    $activeKeys=$Global:TweakToggles.Keys|Where-Object{$Global:TweakToggles[$_] -eq $true}
    $total=($activeKeys|Measure-Object).Count
    if($total -eq 0){Add-Log "No tweaks selected." "#EF4444";return}

    # FIX: AppliedKeys used to be loaded from state.json at startup and never reset before a
    # new Run. Invoke-DedupedGlobalTweak (and the GPU TdrDelay dedup block) checks AppliedKeys
    # and SKIPS the actual registry write if a key was ever marked applied in a *previous*
    # session - even if Windows/an update reverted the setting since. That made NetThrottle,
    # TcpGlobal and GPU TdrDelay permanently "stick" at whatever they were the very first time
    # you ran the tool, no matter how many times you ran it again. Reset per-run so every click
    # of Run actually re-applies the selected tweaks.
    $Global:AppliedKeys = @{}

    # --- Safety check #1: warn about the selected tweaks that change system behavior in ways the user should know about ---
    $riskyMap = [ordered]@{
        "SYS_PauseUpdates"        = "Windows Update will be paused"
        "CLEAN_NoTelemetry"       = "Telemetry / diagnostic data collection will be disabled"
        "CLEAN_NoWER"             = "Windows Error Reporting will be disabled"
        "CLEAN_NoPrintSpooler"    = "Print Spooler service will be disabled (printing will stop working)"
        "SYS_NoBackgroundApps"    = "Background apps will be restricted"
        "CLEAN_RemoveBloat"       = "Pre-installed 'bloatware' apps will be removed"
        "CLEAN_KillBackgroundProcs" = "Common background apps (OneDrive, Discord, Spotify, browser updaters, etc.) will be force-closed if running"
        "CLEAN_DisableLauncherStartup" = "Steam/Discord/Epic/Battle.net/Origin/Ubisoft/Riot/GOG/Spotify will no longer auto-start with Windows (still openable manually)"
        "SYS_ConsumerFeaturesOff" = "Windows 'suggested content' / consumer features will be disabled"
        "SYS_WidgetsOff"         = "Windows Widgets will be disabled"
        "SYS_OneDriveSyncOff"    = "OneDrive sync will be turned off"
        "NET_RemoteAssistanceOff"= "Remote Assistance will be disabled"
        "NET_NoAutoRootCertUpdate" = "Automatic root certificate updates will be disabled"
        "NduDisable"             = "Network Data Usage (Ndu) driver will be disabled"
        "NduDisable_WiFi"        = "Network Data Usage (Ndu) driver will be disabled"
        "NET_Ipv6Disable"        = "IPv6 will be unbound on the wired adapter"
        "NET_Ipv6Disable_WiFi"   = "IPv6 will be unbound on the Wi-Fi adapter"
    }
    $activeRisky=@()
    foreach($k in $riskyMap.Keys){ if($Global:TweakToggles[$k] -and ($activeRisky -notcontains $riskyMap[$k])){ $activeRisky += $riskyMap[$k] } }
    if($activeRisky.Count -gt 0){
        $riskMsg = "The tweaks you selected include changes you should know about:`n`n- " + ($activeRisky -join "`n- ") + "`n`nContinue?"
        $riskConfirm=[System.Windows.MessageBox]::Show($riskMsg,"Sync Project - Please Review",[System.Windows.MessageBoxButton]::YesNo,[System.Windows.MessageBoxImage]::Warning)
        if($riskConfirm -ne [System.Windows.MessageBoxResult]::Yes){ Add-Log "Run cancelled by user at the review step." "#F59E0B"; return }
    }

    # --- Safety check #1b: for the three tweaks that remove/kill/disable actual apps, show the
    # SPECIFIC list of what's actually installed/running on THIS machine (not a generic description)
    # and let the user opt each one out individually without cancelling the whole run. ---
    $skipKeys=@()
    if($Global:TweakToggles["CLEAN_RemoveBloat"]){
        $__installedPkgs = @(Get-AppxPackage -EA SilentlyContinue | Select-Object -ExpandProperty Name)
        $foundBloat=@($Global:BloatList | Where-Object { $__installedPkgs -contains $_ })
        if($foundBloat.Count -gt 0){
            $msg="These pre-installed apps will be REMOVED from this PC:`n`n- "+($foundBloat -join "`n- ")+"`n`nNOTE: this cannot be undone by the Restore Defaults button - to get an app back you'd need to reinstall it from the Microsoft Store.`n`nRemove them?"
            $r=[System.Windows.MessageBox]::Show($msg,"Sync Project - Confirm App Removal",[System.Windows.MessageBoxButton]::YesNo,[System.Windows.MessageBoxImage]::Warning)
            if($r -ne [System.Windows.MessageBoxResult]::Yes){ $skipKeys+="CLEAN_RemoveBloat"; Add-Log "Skipped: app removal (declined by user)." "#F59E0B" }
        }
    }
    if($Global:TweakToggles["CLEAN_KillBackgroundProcs"]){
        $foundProcs=@($Global:KillProcList | Where-Object { Get-Process -Name $_ -EA Ignore } | Select-Object -Unique)
        if($foundProcs.Count -gt 0){
            $msg="These currently-running apps will be FORCE-CLOSED:`n`n- "+($foundProcs -join "`n- ")+"`n`nClose them now? (You can reopen them manually afterward.)"
            $r=[System.Windows.MessageBox]::Show($msg,"Sync Project - Confirm Force-Close",[System.Windows.MessageBoxButton]::YesNo,[System.Windows.MessageBoxImage]::Warning)
            if($r -ne [System.Windows.MessageBoxResult]::Yes){ $skipKeys+="CLEAN_KillBackgroundProcs"; Add-Log "Skipped: force-close background apps (declined by user)." "#F59E0B" }
        }
    }
    if($Global:TweakToggles["CLEAN_DisableLauncherStartup"]){
        $msg="Auto-start on Windows login will be DISABLED for any installed launcher/chat app matching:`n`n- "+($Global:StartupDisableTargets -join "`n- ")+"`n`n(They'll still open fine manually - this only stops them launching automatically.) Continue?"
        $r=[System.Windows.MessageBox]::Show($msg,"Sync Project - Confirm Startup Change",[System.Windows.MessageBoxButton]::YesNo,[System.Windows.MessageBoxImage]::Warning)
        if($r -ne [System.Windows.MessageBoxResult]::Yes){ $skipKeys+="CLEAN_DisableLauncherStartup"; Add-Log "Skipped: disable launcher startup (declined by user)." "#F59E0B" }
    }
    if($skipKeys.Count -gt 0){
        $activeKeys=@($activeKeys | Where-Object { $skipKeys -notcontains $_ })
        $total=($activeKeys|Measure-Object).Count
        if($total -eq 0){ Add-Log "No tweaks left to run after declining the app changes above." "#EF4444"; return }
    }

    # --- Safety check #2: offer to create a System Restore Point first ---
    $rpChoice=[System.Windows.MessageBox]::Show("Create a Windows System Restore Point before applying tweaks? (Recommended, lets you undo everything from Control Panel if something goes wrong)`n`nYes = create restore point, then continue`nNo = continue without one`nCancel = don't run anything","Sync Project - Safety Check",[System.Windows.MessageBoxButton]::YesNoCancel,[System.Windows.MessageBoxImage]::Question)
    if($rpChoice -eq [System.Windows.MessageBoxResult]::Cancel){ Add-Log "Run cancelled by user." "#F59E0B"; return }
    if($rpChoice -eq [System.Windows.MessageBoxResult]::Yes){
        # FIX: Checkpoint-Computer routinely takes anywhere from ~10 seconds to over a minute.
        # It used to run directly on the UI thread inside this click handler with zero feedback,
        # which is exactly what Windows' "(Not Responding)" freeze detector flags - the window
        # looked hung the moment you clicked Run. We now run it in a background job and pump the
        # WPF dispatcher (via an empty Invoke) every 200ms while we wait, which keeps the window
        # responsive/repainting even though we're still waiting on the same click handler.
        Add-Log "Creating System Restore Point (this can take up to a minute, window will stay responsive)..." "#6B7280"
        $rpJob = Start-Job -ScriptBlock {
            try{
                Enable-ComputerRestore -Drive "$env:SystemDrive\" -EA SilentlyContinue
                Checkpoint-Computer -Description "Sync Project - before tweaks" -RestorePointType "MODIFY_SETTINGS" -EA Stop
                "OK"
            } catch { "ERR: $_" }
        }
        while($rpJob.State -eq 'Running'){
            $window.Dispatcher.Invoke([Action]{}, [System.Windows.Threading.DispatcherPriority]::Background) | Out-Null
            Start-Sleep -Milliseconds 200
        }
        $rpResult = Receive-Job -Job $rpJob -Wait -AutoRemoveJob -EA SilentlyContinue
        if($rpResult -like "ERR:*"){
            Add-Log "Could not create a restore point: $rpResult" "#F59E0B"
            $cont=[System.Windows.MessageBox]::Show("Failed to create a restore point.`n`n$rpResult`n`nContinue anyway without one?","Sync Project",[System.Windows.MessageBoxButton]::YesNo,[System.Windows.MessageBoxImage]::Warning)
            if($cont -ne [System.Windows.MessageBoxResult]::Yes){ Add-Log "Run cancelled by user." "#F59E0B"; return }
        } else {
            Add-Log "Restore point created." "#10B981"
        }
    }

    Set-StatusRunning; Add-Log "--- SYNC PROJECT STARTED ---" "#9B5DE5"
    $Global:IsCancelled=$false; $script:_done=0; Update-Progress 0 $total
    $runMap=@{
        "NetThrottle"="Run-NetThrottle";"BcdTimer"="Run-BcdTimer";"TcpGlobal"="Run-TcpGlobal"
        "KbQueue"="Run-KbQueue";"NduDisable"="Run-NduDisable";"GamingMemory"="Run-GamingMemory"
        "FiveMBooster"="Run-FiveMBooster";"GM_FiveMPerfOptions"="Run-FiveMPerfOptions";"GM_FiveMCoreAffinity"="Run-FiveMCoreAffinity";"NET_KillerFix"="Run-KillerFix";"NET_FiveMQos"="Run-FiveMQos";"NET_FiveMFirewall"="Run-FiveMFirewall";"DriverHealth"="Run-DriverHealth"
        "LanOptimize"="Run-LanOptimize";"WifiOptimize"="Run-WifiOptimize"
        "PWR_Throttling"="Run-PwrThrottling";"GM_FSOptim"="Run-FSOptim";"GM_MouseAccel"="Run-MouseAccel"
        "UX_MenuInstant"="Run-MenuInstant";"UX_Notifications"="Run-Notifications"
        "ADV_HPET"="Run-HPET";"GM_SmoothMotion"="Run-MPODisable";"CLEAN_SmoothOptim"="Run-SmoothOptim"
        "NET_NoNagle"="Run-NoNagle";"PWR_UltimatePlan"="Run-UltimatePlan";"SYS_NoCoreParking"="Run-NoCoreParking";"GM_HAGS"="Run-HAGS"
        "NET_PowerSaving"="Run-NetPowerSaving";"NET_USBSelSuspend"="Run-UsbSelSuspend"
        "SYS_TimerRes"="Run-TimerRes";"SYS_PauseUpdates"="Run-PauseUpdates"
        "GM_GameMode"="Run-GameMode";"GM_NoGameDVR"="Run-NoGameDVR";"GM_GameBarOff"="Run-GameBarOff";"GM_StandbyClean"="Run-StandbyClean"
        "CLEAN_NoSearchIndex"="Run-NoSearchIndex";"CLEAN_NoTelemetry"="Run-NoTelemetry";"CLEAN_NoStorageSense"="Run-NoStorageSense"
        "SYS_Win32Priority"="Run-Win32Priority";"GM_MMCSS"="Run-MMCSS"
        "NET_TcpTimedWait"="Run-TcpTimedWait";"NET_PortRange"="Run-PortRange";"NET_QoSReserve"="Run-QoSReserve"
        "GM_MouseQueue"="Run-MouseQueue";"GM_NoStickyKeys"="Run-NoStickyKeys"
        "SYS_NoBackgroundApps"="Run-NoBackgroundApps";"CLEAN_NoWER"="Run-NoWER";"CLEAN_NoPrintSpooler"="Run-NoPrintSpooler"
        "GPU_TdrDelay_Nvidia"="Run-GpuTdrDelay";"GPU_TdrDelay_Amd"="Run-GpuTdrDelay";"GPU_NvidiaPowerMode"="Run-NvidiaPowerMode";"GPU_NvidiaTelemetryOff"="Run-NvidiaTelemetryOff"
        "GPU_NvidiaMSIMode"="Run-NvidiaMSIMode";"GPU_NvidiaOverlayOff"="Run-NvidiaOverlayOff"
        "GPU_AmdUlps"="Run-AmdUlps";"GPU_AmdEventsUtil"="Run-AmdEventsUtil"
        "GPU_AmdMSIMode"="Run-AmdMSIMode";"GPU_AmdCrashDefenderOff"="Run-AmdCrashDefenderOff"
        "NetThrottle_WiFi"="Run-NetThrottle";"TcpGlobal_WiFi"="Run-TcpGlobal";"NduDisable_WiFi"="Run-NduDisable"
        "NET_NoNagle_WiFi"="Run-NoNagle";"NET_PowerSaving_WiFi"="Run-NetPowerSaving"
        "NET_TcpTimedWait_WiFi"="Run-TcpTimedWait";"NET_PortRange_WiFi"="Run-PortRange";"NET_QoSReserve_WiFi"="Run-QoSReserve"
        "NET_LanJumboFrame"="Run-LanJumboFrame";"NET_LanInterruptModeration"="Run-LanInterruptModeration"
        "NET_WifiPowerSaveMode"="Run-WifiPowerSaveMode";"NET_WifiRoamingAggressiveness"="Run-WifiRoamingAggressiveness"
        "NET_DnsFast"="Run-DnsFastLan";"NET_DnsFast_WiFi"="Run-DnsFastWifi"
        "NET_DeliveryOptOff"="Run-DeliveryOptOff";"NET_DnsCacheAggressive"="Run-DnsCacheAggressive"
        "SYS_BottleneckCheck"="Run-BottleneckCheck";"GPU_ClearShaderCache"="Run-ClearShaderCache"
        "CLEAN_ClearTempJunk"="Run-ClearTempJunk";"CLEAN_ClearFiveMCache"="Run-ClearFiveMCache"
        "CLEAN_RemoveBloat"="Run-RemoveBloat";"CLEAN_KillBackgroundProcs"="Run-KillBackgroundProcesses";"CLEAN_DisableLauncherStartup"="Run-DisableLauncherStartup"
        "NET_Ipv6Disable"="Run-Ipv6DisableLan";"NET_Ipv6Disable_WiFi"="Run-Ipv6DisableWifi"
        "NET_RssEnable"="Run-RssEnable";"NET_FlowControlOff"="Run-FlowControlOff"
        "DEF_GameExclusion"="Run-GameExclusion";"SYS_PageFileAuto"="Run-PageFileAuto"
        "NET_Ipv6Transition"="Run-Ipv6TransitionDisable";"NET_DnsClientPolicy"="Run-DnsClientPolicy"
        "NET_LltdDisable"="Run-LltdDisable";"NET_BitsNoLimit"="Run-BitsNoLimit";"NET_NetbiosDisable"="Run-NetbiosDisable"
        "NET_NcsiNoActiveProbe"="Run-NcsiNoActiveProbe";"NET_NoAutoRootCertUpdate"="Run-NoAutoRootCertUpdate"
        "SYS_NoBkgndGPRefresh"="Run-NoBkgndGPRefresh";"SYS_NoSmartScreenCheck"="Run-NoSmartScreenCheck"
        "NET_RemoteAssistanceOff"="Run-RemoteAssistanceOff"
        "SYS_OneDriveSyncOff"="Run-OneDriveSyncOff";"SYS_WidgetsOff"="Run-WidgetsOff";"SYS_ConsumerFeaturesOff"="Run-ConsumerFeaturesOff";"BabyDek_TcpFull"="Run-BabyDekTcpFull";"BabyDek_RegParams"="Run-BabyDekRegParams";"SYS_Win32Prio_38"="Run-Win32Prio38";"KbQueue16"="Run-KbQueue16";"MouseQueue16"="Run-MouseQueue16";"CitizenFX_Ini"="Run-CitizenFXIni";"GPU_ImportNip"="Run-ImportNip";"SYS_TscSyncEnhanced"="Run-TscSyncEnhanced";"MMCSS_GamesProfile"="Run-MMCSSGamesProfile";"KaiPrime_Full"="Run-KaiPrimeFull";"KaiPrime_QoS"="Run-KaiPrimeQoS";"KaiPrime_NicTweaks"="Run-KaiPrimeNicTweaks";"KaiPrime_InternetReg"="Run-KaiPrimeInternetReg";"KaiPrime_FiveMPriority"="Run-KaiPrimeFiveMPriority";"Drew_RayzxPolicy"="Run-DrewRayzx";"CitizenDevtoolsDll"="Run-CitizenDevtoolsDll";"SetWallpaper"="Run-SetWallpaper";"GTA_SettingsXml"="Run-GTASettingsXml";"VC90_Dlls"="Run-VC90Dlls";"FivemLag_QoS"="Run-FivemLagQoS";"Batch1_Tweaks"="Run-Batch1Tweaks";"RealmSoothing"="Run-RealmSoothing";"Auto_CitizenAssets"="Run-AutoCitizenAssets";"X3d_IntelBat"="Run-X3dIntelBat";"T_Bat"="Run-TBat";"Boost_FPS"="Run-BoostFps";"Zephyshade_Pow"="Run-ZephyshadePow";"Zephyr_Nip"="Run-ZephyrNipImport";"Queen_Optimize"="Run-QueenOptimize";"Reshade_Installer"="Run-ReshadeInstaller";"Startup_DCS"="Run-StartupDcs";"OLED_Theme"="Run-OledTheme"
    }
    $restartRequiredKeys=@("BcdTimer","ADV_HPET","GM_HAGS","SYS_NoCoreParking","SYS_TscSyncEnhanced")
    $restartRequired=[bool](@($activeKeys | Where-Object { $restartRequiredKeys -contains $_ }).Count -gt 0)
    $timer=New-Object System.Windows.Threading.DispatcherTimer
    $timer.Interval=[TimeSpan]::FromMilliseconds(180)
    $keyQueue=[System.Collections.Queue]::new($activeKeys)
    $script:_total = $total; $script:_done = 0
    $timer.Add_Tick({
        if($keyQueue.Count -eq 0 -or $Global:IsCancelled){
            $timer.Stop();Save-TweakState
            Add-Log "--- FIVEM OPTIMIZE PROFILE COMPLETE ---" "#10B981"
            if(-not $Global:IsCancelled){
                if($restartRequired){
                    Add-Log "At least one selected advanced tweak requires a restart to fully take effect." "#F59E0B"
                    [System.Windows.MessageBox]::Show("Your selected tweaks have been applied.`n`nAt least one advanced option needs a PC restart to fully take effect.","FiveM Optimize - Complete",[System.Windows.MessageBoxButton]::OK,[System.Windows.MessageBoxImage]::Information)|Out-Null
                    Set-CurrentTask "Complete. Restart required for selected advanced options."
                } else {
                    Add-Log "Optimize profile applied. Start or return to FiveM; no restart is required for this profile." "#10B981"
                    [System.Windows.MessageBox]::Show("FiveM Optimize profile has been applied.`n`nNo restart is required. Priority and performance tweaks are now active via IFEO/System.","FiveM Optimize - Complete",[System.Windows.MessageBoxButton]::OK,[System.Windows.MessageBoxImage]::Information)|Out-Null
                    Set-CurrentTask "Complete. Ready for FiveM."
                }
            }
            Set-StatusDone;Update-Progress $script:_total $script:_total;return
        }
        $k=$keyQueue.Dequeue();$script:_done++;Update-Progress $script:_done $script:_total
        if($runMap.ContainsKey($k)){
            $fnName=$runMap[$k]
            try{
                & (Get-Command $fnName -CommandType Function).ScriptBlock $k
                Add-Log "[OK] $k" "#10B981"
            } catch {
                Add-Log "[FAIL] $k`: $_" "#EF4444"
            }
        } else { Set-CurrentTask $k; Add-Log "[OK] $k applied" "#10B981" }
    }.GetNewClosure())
    $timer.Start()
})

Add-Log "> FiveM Balanced console initialised." "#9B5DE5"
Add-Log "> Safe client-side profile selected. Server/ISP ping is not changed by local tweaks." "#6B7280"

$window.Add_KeyDown({
    param($s,$e)
    if($e.Key -eq [System.Windows.Input.Key]::Escape){
        if($CategoryOverlay.Visibility -eq "Visible"){ Close-CategoryDetail; $e.Handled=$true }
    } elseif(($e.Key -eq [System.Windows.Input.Key]::Return -or $e.Key -eq [System.Windows.Input.Key]::Enter)){
        if($CategoryOverlay.Visibility -ne "Visible" -and (-not $SearchBox.IsFocused)){
            $BtnRun.RaiseEvent((New-Object System.Windows.RoutedEventArgs([System.Windows.Controls.Button]::ClickEvent)))
            $e.Handled=$true
        }
    }
})

$window.Add_Closing({
    if($Global:BackgroundJobs){
        foreach($j in $Global:BackgroundJobs){
            try{ Stop-Job -Job $j -EA SilentlyContinue; Remove-Job -Job $j -Force -EA SilentlyContinue }catch{}
        }
    }
})

Update-PresetGlowConsistency
try {
    $sc = Set-FiveMLaunchShortcut
    Add-Log ("Auto shortcut: {0} updated" -f $sc.Updated) "#A78BFA"
} catch {
    Add-Log ("Auto shortcut skipped: {0}" -f $_.Exception.Message) "#6B7280"
}
try {
    Add-Log "Ready. Use CHECK UPDATE for realtime updates." "#38BDF8"
    Start-FiveMOptimizeUpdateCheck
} catch {}
try {
    $window.ShowDialog() | Out-Null
} catch {
    $msg = $_.Exception.Message
    try { [System.Windows.MessageBox]::Show($msg, "FiveM Optimize") | Out-Null } catch { Write-Host $msg; Start-Sleep -Seconds 20 }
}

